import React, { useLayoutEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import { Tabs, Button, ButtonGroup, Popper, Grow, ClickAwayListener, MenuItem, Paper, MenuList } from '@mui/material';
import { useState, memo, useCallback } from 'react';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import TabsUnstyled from '@mui/base/TabsUnstyled';
import { Link } from 'react-router-dom';
import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown';
import { useTheme } from '@emotion/react';

function TabsList(props) {
    const { onChange, tabsProps, indicator, ...otherProps } = props;
    const [value, setValue] = useState(0);
    const [options, setOptions] = useState({
        anchor: null,
        values: [],
        selected: null,
        setSelectedValue: null,
        indexTabGroup: null,
        setSelectedValue: null
    });
    const currentTheme = useTheme();
    const handleChange = useCallback((event ,newValue) => {
        setValue(newValue);
        if(onChange) onChange(event, newValue);
    },[onChange]);

    const handleChangeOptions = (event, option) => {
        onChange(event, {value : option, index: options.indexTabGroup});
        if(options.setSelectedValue) options.setSelectedValue(option);
        setOptions({...options, selected: option });
        handleClose();
    };
    const handleClose = () => {
        setOptions({
            anchor: null,
            values: [],
            selected: null,
            indexTabGroup: null,
            setSelectedValue: null
        });
    };
    const tabs = React.Children.toArray(props.children)
    .map((element, index) => (React.cloneElement(element, 
        {
            ...otherProps, 
            ...(element.type.name === 'TabGroup' ? {optionsParams: options, setOptions, indexTabGroup: index} : {})      
        })));
    const theme = createTheme({
        ...currentTheme,
        components: {
            MuiTabs: {
                styleOverrides: {
                    indicator: {
                        textAlign:'justify',
                        ...(indicator ? {}: {display: 'none'})
                    },
                },
            },
        }
    });

    return (
        <ThemeProvider theme={theme}>
            <Tabs  
                value={value} 
                onChange={handleChange}
                variant="scrollable"
                {...tabsProps}
            >
                {tabs}
            </Tabs>
            <Popper
                open={Boolean(options.anchor)}
                anchorEl={options.anchor}
                disablePortal
            >
                <Paper>
                    <ClickAwayListener onClickAway={handleClose}>
                        <MenuList >
                        {options.values.map((option, index) => (
                            <MenuItem
                            key={index}
                            selected={option === options.selected}
                            onClick={(event) => handleChangeOptions(event, option)}
                            >
                            {option}
                            </MenuItem>
                        ))}
                        </MenuList>
                    </ClickAwayListener>
                </Paper>
            </Popper>
        </ThemeProvider>
    )
}

TabsList.propTypes = {
    onChange: PropTypes.func,
    indicator: PropTypes.bool,
    tabsProps: PropTypes.object
}

TabsList.defaultProps = {
    onChange() {},
    indicator:true,
    tabsProps:{}
}

export function Tab(props) {
    const {
        indicator, 
        selectionFollowsFocus, 
        value, 
        onChange, 
        textColor, 
        selected,
        color,
        link,
        defaultValue,
        variantFocus,
        ...otherProps 
    } = props;
    const refLink = useRef();

    const handleValue = useCallback((event) => {
        if(!selected) onChange(event, defaultValue ? ({value : defaultValue, index: value}) : value);
        if(refLink.current) refLink.current.click();
    },[value, onChange]);
   
    return (
        <TabsUnstyled >
            {link && <Link ref={refLink} style={{display: 'none'}}  to={link} />}
                <Button 
                    onClick={handleValue}
                    {...otherProps}
                    {...(variantFocus ? {
                        variant: selected ? 'contained' : 'outlined' 
                    } : {
                        color : selected ? color : 'inherit'
                    })}
                >
                    {props.label}
                </Button>
        </TabsUnstyled>
        );
}

export function TabGroup(props) {
    const {
        indicator, 
        selectionFollowsFocus, 
        value, 
        onChange, 
        textColor, 
        selected,
        color,
        link,
        defaultValue,
        variantFocus,
        options,
        optionsParams,
        indexTabGroup,
        setOptions,
        ...otherProps 
    } = props;

  const [open, setOpen] = React.useState(false);
  const anchorRef = React.useRef(null);
  const [selectedValue, setSelectedValue] = useState(defaultValue);

  const handleToggle = () => {
    setOptions(
        (optionsParams.anchor && (indexTabGroup === optionsParams.indexTabGroup)) ? 
        {
            ...optionsParams, 
            anchor: null, 
            selected: null, 
            values: [], 
            indexTabGroup: null,
            setSelectedValue: null,
        } :
        {
            ...optionsParams, 
            anchor: anchorRef.current, 
            selected: selectedValue, 
            values: options, 
            indexTabGroup: indexTabGroup,
            setSelectedValue,
        })
  };
    const handleValue = useCallback((event) => {
        if(!selected) onChange(event, defaultValue ? ({value : defaultValue, index: value}) : value);
    },[value, onChange])
  return (
    <TabsUnstyled >
      <ButtonGroup 
        sx={{
                m:'10px 10px',
                mb: -1
            }}
        {  ...otherProps }
        {...(variantFocus ? {
            variant: selected ? 'contained' : 'outlined' 
        } : {
            color : selected ? color : 'inherit'
        })}
        ref={anchorRef} 
        aria-label="split button"
      >
        <Button size="small" ref={anchorRef} onClick={handleValue}>{selectedValue}</Button>
        <Button
          size="small"
          onClick={handleToggle}
        >
          <ArrowDropDownIcon />
        </Button>
      </ButtonGroup>
    </TabsUnstyled>
  );
}

export default memo(TabsList);