import { useData, useSetting } from "../../treatments/globalData";
import AppContentBox from "../AppContentBox";
import AppHeader from "../AppHeader";
import {
    Box, 
    IconButton, 
    Tooltip, 
    useMediaQuery
} from '@mui/material'
import SettingsIcon from "@mui/icons-material/Settings";
import NoteAltIcon from '@mui/icons-material/NoteAlt';
import MenuIcon from '@mui/icons-material/Menu';
import EditorText from "./EditorText";

function Note() {
    const { text, screen } = useData();
    const isMiddleScreen = useMediaQuery(screen);
    const [value, action] = useSetting();
    return(
        <AppContentBox>
            <AppHeader
                title={text.applications.note.title}
                icon={
                    <NoteAltIcon
                        sx={{position: 'relative', top: '5px'}}
                    />
                }
                sx={{
                    zIndex: theme => theme.zIndex.modal
                }}
            >
                {isMiddleScreen  ?
                (<Box 
                sx={{
                    display:'flex', 
                    flexDirection: 'row', 
                    alignItems: 'center',
                    flex:1,
                    '&>*': {
                        m:1,
                    }
                }}>
                    
                    <Box sx={{ flexGrow: 1, ml: 10}}>
                    </Box>
                    <Tooltip arrow title={'paramètre'}>
                        <IconButton 
                            onClick={action.onOpen('settingOptions')}
                        sx={{mr:1}}>
                                <SettingsIcon/> 
                        </IconButton>
                    </Tooltip>
                </Box>):
                (<Box>
                    <IconButton
                    onClick={action.onOpen('settingNavMobile')}
                    >
                        <MenuIcon/>
                    </IconButton>
                </Box>)
            }
            </AppHeader>
            <Content/>
        </AppContentBox>
    );
}
function Content(props) {

    return(
        <EditorText/>
    )
}
export default Note;