import { forwardRef, useCallback, useEffect, useState } from "react";
import { Box } from "@mui/system";
import { FormControl, FormHelperText, InputLabel, MenuItem, Select, Typography } from "@mui/material";
import ErrorIcon from '@mui/icons-material/Error';
import CheckIcon from "@mui/icons-material/Check";
import { useData } from "../treatments/globalData";

function SelectList(props, ref) {
    const { 
            items, 
            label, 
            checking, 
            icon, 
            helperTextSuccess, 
            value:defaultValue,
            onChange,
            ...otherProps
        } = props;
    const {text:input} = useData();
    const { input:text } = input;
    const [value, setValue] = useState(defaultValue || '');
    const handleChange = useCallback((event) => {
        if(typeof onChange === 'function') onChange(event);
        setValue(event.target.value)
    },[])
 
    const color = checking ? (
        ( new RegExp (`^${items.map((item) =>item.value).join('|')}$`) )
        .test(value) ? "primary" : "error") : "primary";
    useEffect(() => {
        if(ref) ref.current = value === '' ? null : value;
    })

    return(
        <Box sx={{ minWidth: 120 }}>
            <FormControl {...otherProps} color={color} fullWidth>
                <InputLabel id="simple-select-label">{label}</InputLabel>
                <Select
                    labelId="simple-select-label"
                    id="demo-simple-select"
                    value={value}
                    label={label}
                    onChange={handleChange}
                >
                    {items.map((item, index) => 
                    (<MenuItem selected={item.selected} key={index} value={item.value}>{item.title}</MenuItem>))}
                </Select>
                { checking &&  
                <FormHelperText id="outlined-weight-helper-text">
                <Typography color={color} variant="caption" component="span"> 
                    {
                    icon && 
                         ( Boolean(value) ?  <ErrorIcon sx={{fontSize:"15px", position:'relative', top:2}} />
                          : <CheckIcon sx={{fontSize:"15px", position:'relative', top:2}} />) 
                    }  { 
                       color === 'primary' ? helperTextSuccess : text.error.empty
                    } 
                </Typography>
           </FormHelperText>}
            </FormControl>
      </Box>
    )
}

export default forwardRef(SelectList);