import { Box, Card, CardActionArea, CardContent, CardHeader, CardMedia, Typography } from '@mui/material';
import Button from '@mui/material/Button'
import { Link } from 'react-router-dom';

function FrameApp(props) {
    const {alt, image, height, title, content, buttonTitle, buttonAction, link } = props;

    const linkComponent = {
        LinkComponent: Link,
        to: link
    }

    return(
        <Box component={Card}>
            <Box component={CardActionArea}
                {...(link ? linkComponent : {})}
            >
                <CardMedia
                    component="img"
                    alt={alt}
                    height={ height || '100'}
                    image={image}
                />
                <CardHeader
                    title={title}
                    component="div"
                    sx={{mt: 0, mb:0, pt:0, pb:0}}
                />
                <CardContent>
                    <Typography paragraph sx={{height:100}} variant="body2" color="text.secondary">
                    {content}
                    </Typography>
                </CardContent>
            </Box>
        </Box>
    );
}

export default FrameApp;