import {
   Box, 
   Button, 
   OutlinedInput,
   IconButton
} from '@mui/material';
import { forwardRef, useEffect, useRef, useState } from 'react';
import BackspaceIcon from '@mui/icons-material/Backspace';

function CodeField(props, ref) {
   const { cases, action } = props;
   const fields = [];
   const caseNumbers = cases || 6;
   const inputRefNext = useRef();
   const inputRefPrevious = useRef();
   const keyBackspaceRef = useRef();
   const handlerChange = (index) => (event) => {
      const newInputValues = [...values.inputValues];
      const value = /[0-9]{1,1}/.test(event.target.value) ? event.target.value : '';
      newInputValues[index] = value.charAt(0);
      setValues({ 
         ...values,
         inputValues: [...newInputValues], 
         currentInput: value === '' ? 
         values.currentInput : values.currentInput + 1
         })
      if(Boolean(value) && inputRefNext.current)
         inputRefNext.current.focus();
   }
   for(let i = 0; i < caseNumbers; i++)
      fields.push({
         sx: {
            width: 50,
            height: 50
         },
         type: 'text',
         inputProps: {
            sx: {
               fontWeight: 1000,
               fontSize: '2em',
               textAlign: 'center'
            }
         }
      })
   const [values, setValues]  = useState({
      inputValues: [...fields.map(() => '')],
      currentInput: 0,
      anchorEl: null,
      anchorIndexEl: null
   })
   const handleClick = (event) => {
      const newInputValues = [...values.inputValues];
      if(newInputValues[0] !== '' ) {
      const index = values.currentInput - 1;
      newInputValues[index] = '';
      setValues({ 
         ...values,
         inputValues: [...newInputValues], 
         currentInput: index
         });
      } 
      if(inputRefPrevious.current)
         inputRefPrevious.current.focus();
   }
   
   const handleKey = (event) => {
      if(event.code.toString().toLowerCase() === 'backspace' && keyBackspaceRef.current) 
         keyBackspaceRef.current.click()
   };
   
   useEffect(() => {
      if(typeof action === 'function' && values.currentInput === (caseNumbers))
         action(parseInt(values.inputValues.join('')))
   })
   return(
      <Box>
         <Box
            sx={{
             textAlign: 'center',
             p:1,
            '& > *': { 
               ml: .1, 
               mr: .1, 
               display: 'inline-lock'
               }
            }}
            onKeyDown={handleKey}
         >
             {fields.map((fieldProps, index) => 
               (<OutlinedInput
                  key={index}
                  {...fieldProps}
                  value={values.inputValues[index]}
                  onChange={handlerChange(index)}
                  inputRef={((values.currentInput + 1) === index) ? inputRefNext : 
                     ((values.currentInput - 1) === index) ? inputRefPrevious : null
                  }
                  readOnly={!(index === values.currentInput)}
                  autoFocus={(index === values.currentInput)}
               />)
             )}
             <IconButton
                sx={{
                  width: 50,
                  height: 50,
                  mt: -1,
                  ml: 1
               }}
               onClick={handleClick}
               ref={keyBackspaceRef}
             >
                <BackspaceIcon/>
            </IconButton>
         </Box>
      </Box>
   )
}

export default forwardRef(CodeField);