import { useEffect, useLayoutEffect, useState } from "react";

function useSystemTheme(props) {
    const darkThemeMediaquery = window.matchMedia("(prefers-color-scheme: dark)");
    const [theme, setTheme] = useState( darkThemeMediaquery.matches ? 'dark': 'light');
    const handleChange = (event) => {
        setTheme(event.target.matches ? 'dark': 'light');
    }
    useLayoutEffect(()=> {
        darkThemeMediaquery.onchange = handleChange;
    });
    useEffect(()=> (() => {
        darkThemeMediaquery.onchange = null;
    }));

    return(theme)
}

export default useSystemTheme;