import { 
    Grid, 
    Dialog, 
    DialogTitle, 
    Toolbar, 
    Typography, 
    IconButton, 
    DialogContent, 
    Box, 
    Button, 
    Divider, 
    FormControl, 
    Snackbar,
    Alert
} from '@mui/material'
import CloseIcon from '@mui/icons-material/Close';
import { Fragment, useContext, useRef, useState } from 'react';
import { CurrentSession } from '../components/Auth';
import SelectList from '../components/SelectList';
import fileExtensionBase from '../config/fileExtensionBase';
import { getFileExtension, getFileName } from '../treatments/getFileExtension';
import LocalSeeIcon from '@mui/icons-material/LocalSee';
import VideocamIcon from '@mui/icons-material/Videocam';
import AudiotrackIcon from '@mui/icons-material/Audiotrack';
import ArticleIcon from '@mui/icons-material/Article';
import QuizIcon from '@mui/icons-material/Quiz';
import FieldContoller from '../components/FieldController';
import axios from 'axios';
import serverPath from '../treatments/severPath';
import objectChecked from '../treatments/objectChecked';
import PerfectScrollbar from 'react-perfect-scrollbar';

const formats = [
    { label: 'photo', title: 'format images', icon: <LocalSeeIcon/> },
    { label: 'video', title: 'format videos', icon: <VideocamIcon/> },
    { label: 'audio', title: 'format audios', icon: <AudiotrackIcon/> },
    { label: 'doc', title: 'format documents', icon: <ArticleIcon/> },
    //{ label: 'video', title: 'format inconnu', icon: <QuizIcon/> }   
];

function SendForm(props) {

    const[currentSession] = useContext(CurrentSession);
    const { docTypes } = currentSession.geidConfig
    const [fieldDocType, setFieldDocType] = useState(null);
    const [values, setValues] = useState({
        error: null,
        message: null,
        checking: false,
        alertSnack: false,
    });
    const { type:docType, title:docTitle } = props;
    const docs = docTypes.map((doc, index) => ({title: doc.name, value: index }));
    const docIndex = useRef('');
    const subDocIndex = useRef('');

    const title = useRef('');
    const author = useRef('');
    const type = useRef('');
    const describe = useRef('');
    const object = useRef('');
    const designation = useRef('');

    const subDocs = Boolean(
        fieldDocType !== null && docTypes[fieldDocType].subtypes
        ) ? docTypes[fieldDocType].subtypes
    .map((subDoc, index) => ({title: subDoc, value: index })) : [];
    
    const handleChange = (event) =>  {
            setFieldDocType(event.target.value);
    }

    const handleSendData = () => {
        const route = serverPath('api/stuff/frozen');
        const fileInfo = {
            description: describe.current,
            ...(props.id === 'mediaLibrary' ? {
                title: title.current, 
                ...(props.type === 'documents' ? {
                    type: type.current, 
                    author: author.current,
                } : {})
            } : {}),
            ...(props.id === 'archives' ? {
                designation: designation.current,
			    object: object.current,
                type: (
                    docTypes[fieldDocType] && 
                    (subDocs.length ? subDocs[subDocIndex.current] 
                        : true) ) ? {
                    type: docTypes[fieldDocType].name,
                    ...(subDocs.length ? {
                        subtype: subDocs[subDocIndex.current] && subDocs[subDocIndex.current].title,
                    }:{}) 
                }: null,
            } : {})
            
        }
        if(objectChecked(fileInfo))
            axios({
                method: 'post',
                url: route,
                headers: {
                    'Authorization': `Bearer ${currentSession.token}`
                  },
                data: {
                    where: props.type + '/' + props.file.name,
                    userId: currentSession.id, 
                    datas: {
                    frozenType: props.id === 'archives' ? 'ressource' : ({
                        videos: 'film',
                        documents: 'book',
                        images: 'image'
                    })[props.type],
                    ...fileInfo
                    }
                }
            }).then((result) => {
                setValues({...values, alertSnack: true,
                    error: null,
                    message: `${props.file.name.length > 35 ? props.file.name.slice(0, 35) + '...' : props.file.name } 
                    est envoyé avec succès`
                })
            }).catch((error) => {
                console.log(props.file.name);
                setValues({...values, alertSnack: true, error:true,
                    message: `l'envoi de 
                    ${props.file.name.length > 35 ? props.file.name.slice(0, 35) + '...' : props.file.name } 
                    a echoué !`
                })
            })
        else setValues({...values, checking: true});
        props.onClose();
    }

    return(
        <Fragment> 
            <Dialog
                open={props.open}
                
            >
                <DialogTitle id="scroll-dialog-title" sx={{p:0}}>
                    <Toolbar>
                        <Typography color="primary" sx={{flexGrow:1}} variant="h6" component="div">
                            Envoyer vers {docTitle && docTitle.toLowerCase()}
                        </Typography>
                        <IconButton
                        edge="start"
                        aria-label="close"
                            onClick={props.onClose}
                        >
                            <CloseIcon />
                        </IconButton>
                    </Toolbar>
                </DialogTitle>
                <DialogContent sx={{width:550}}>
                    <Box
                        >
                        { 
                        props.file &&
                            formats.filter((item) => ~fileExtensionBase[item.label].indexOf(getFileExtension(props.file.name)))
                            .map((item, index) => (
                                <Fragment key={index}>
                                    {item.icon} <span style={{position: 'relative', top: '-5px'}}>{item.title}
                                    </span>
                                    <Divider/>
                                    <Box component={PerfectScrollbar} sx={{mb:.5}}>
                                        <Typography variant="caption" paragraph color="text.secondary">
                                            {getFileName(props.file.name)}
                                        </Typography>
                                    </Box>
                                </Fragment>
                            ))
                        }  
                </Box>
                    <Grid container spacing={1}>
                        {props.id === 'mediaLibrary' &&
                        (<Fragment>
                            <Grid item md={12}>
                                <FieldContoller
                                    id="title"
                                    label="Titre"
                                    type="text"
                                    fullWidth
                                    size="small"
                                    ref={title}
                                    regExp={/\w/}
                                    checking={values.checking}
                                />
                            </Grid>
                            {props.type === 'documents' &&
                            (<Fragment>
                                <Grid md={6} item>
                                    <FieldContoller
                                        id="type"
                                        label="Type"
                                        size="small"
                                        ref={type}
                                        regExp={/\w/}
                                        checking={values.checking}
                                        fullWidth
                                    />
                                </Grid>
                                <Grid md={6} item>
                                    <FieldContoller
                                        id="author"
                                        label="Auteur"
                                        size="small"
                                        ref={author}
                                        regExp={/\w/}
                                        checking={values.checking}
                                        fullWidth
                                        
                                    />
                                </Grid>
                            </Fragment>)}
                        </Fragment>)}
                {props.id === 'archives' &&
                (<Fragment>
                        <Box xs={12} md={6} item component={Grid}>
                            <SelectList
                                label="Type de document"
                                items={docs}
                                size="small"
                                //checking={values.checked}
                                value={docIndex.current}
                                ref={docIndex}
                                fullWidth
                                checking={values.checking}
                                onChange={handleChange}
                            />
                        
                        </Box>
                        <Box  xs={12} md={6} item component={Grid}>
                            <SelectList
                                label="Sous type"
                                items={subDocs}
                                size="small"
                                //checking={Boolean(secteurFields.length) && values.checked} 
                                disabled={subDocs.length === 0}
                                value={subDocIndex.current}
                                ref={subDocIndex}
                                checking={values.checking}
                                fullWidth
                            />
                            
                        </Box>
                        <Box xs={12} md={6} item component={Grid}>
                            <FieldContoller
                                label="object"
                                size="small"
                                fullWidth
                                ref={object}
                                regExp={/\w/}
                                checking={values.checking}
                            />
                        
                        </Box>
                        <Box  xs={12} md={6} item component={Grid}>
                            <FieldContoller
                                label="designation"
                                size="small"
                                fullWidth
                                ref={designation}
                                regExp={/\w/}
                                checking={values.checking}
                            />
                            
                        </Box>
                    </Fragment>)}

                        <Grid item md={12}>
                            <FieldContoller
                                id="description"
                                label="Description"
                                multiline={true}
                                rows={3}
                                type="text"
                                size="small"
                                fullWidth
                                regExp={/\w/}
                                checking={values.checking}
                                ref={describe}
                            />
                        </Grid>
                    </Grid>

                </DialogContent>

                <Box sx={{m:1, flex:1}}>
                    <Button 
                    variant='contained'
                    size="small"
                    onClick={handleSendData}
                    >Envoyer</Button>
                </Box>

            </Dialog>
            <Snackbar
                open={Boolean(values.alertSnack)}
                autoHideDuration={2000}
                onClose={() => {
                setValues({...values, alertSnack: false, message: '',  })
            } }
            anchorOrigin={{
                vertical: 'bottom',
                horizontal: 'right'
            }}
            action={
                <IconButton
                    size="small"
                    color="inherit"
                    onClick={() => {
                        setValues({...values, alertSnack: false, error: null, message: ''})
                    }}
                >
                    <CloseIcon/>
                </IconButton>
                }
            >
               <Alert severity={values.error ? 'error' : 'success'}>
                    {values.message} 
               </Alert>
            </Snackbar> 
        </Fragment> 
    );
}

export default SendForm;