function bytesConverter(size, stric) {
    const stictMode = stric ? 1024 : 1000;
	size = Math.abs(parseInt(size, 10));
	const sizes = [
        [1, 'octets'], 
        [stictMode, 'ko'], 
        [Math.pow(stictMode, 2), 'Mo'], 
        [Math.pow(stictMode, 3), 'Go'], 
        [Math.pow(stictMode, 4), 'To'],
        [Math.pow(stictMode, 5), 'Po'],
        [Math.pow(stictMode, 6), 'Eo'],
        [Math.pow(stictMode, 7), 'Zo'],
        [Math.pow(stictMode, 7), 'Yo'],
        [Math.pow(stictMode, 7), 'Yo'],
    ];

	let value = null;
    
    sizes.forEach((item, i) => {
        if((value === null) && size<sizes[i][0])
            value = (size/sizes[i-1][0]).toFixed(2)+' '+sizes[i-1][1];
    })
    return value;

}
export default bytesConverter;
