import { useContext, createContext, useState } from "react";
import * as localStorageData from './localStorageData';
const CONTEXT = createContext({});
const SETTING = createContext({});
export const useSetting = () =>  useContext(SETTING);
export const SettingProvider = SETTING.Provider;
export const DataProvider = CONTEXT.Provider;
export const useData = ()=> useContext(CONTEXT);
export const useGlobalState = () => {
    const [values, setValues] = useState(localStorageData.get());
    const actions = {
        handleChangeGlobalProp(prop, value) {
            setValues({...values, [prop]: value });
        },
        handleTheme(theme) {
            localStorageData.set('local', (values.local ? {...values.local, theme: theme} : {theme: theme}))
            setValues({...values, local: { ...values.local, theme: theme} });
        }
    }
    return [values,actions];
};

export const useSettingTreatment = () => {
    const [values, setValues] = useState({ 
        settingOptions: null,
        settingNavMobile: null,
        appsMenu: null,
        treeStruture: null,
        workspace: null,
        uploadsNavWorkspace: null,
        profileNav: null,
        logIn: null
    });
    
    const actions = {
        onClose (prop) {
            return() => {
                setValues({...values, [prop]: null })
            }
        },
        onOpen(prop) {
            return (event) => {
                setValues({...values, [prop]: event ? event.target : true })
            }
        }
    };
    return [values, actions]
}