export function Timer(props) {
   const {max, min, reverse, type, stop, action, ...otherProps}  = props;
   const initValue = reverse ? max : min;
   const initState = isNaN(initValue) ? (new Date()) : initValue;
   
   const [time, setTime] = useState({
      start: true,
      value: initState
   });
   
   const handleTimer = () => {
         const value = (time.value instanceof Date) ? (new Date()) : (reverse ?
            (time.value === min ? initValue : time.value - 1) :
            (time.value === max ? initValue : time.value + 1)
         );

         setTime({...time, value: value});
   }
   const handleToggleState = () => {
      setTime({...time, start: !time.start});
   }
   const handleInit = () => {
      if(timer) window.clearTimeout(timer);
      setTime({start: true, value: initValue});
   };
   const handlePlay = () => {
      setTime({...time, start: true});
   };
   const handlePause = () => {
      if(timer) window.clearTimeout(timer);
      setTime({...time, start: false});
   };
  
   let timer = time.start && window.setTimeout(handleTimer, 1000);;

   useEffect(() => {

      if(timer && (reverse ? time.value === min : time.value === max)) {  
           if(typeof action === 'function') 
            action({
               time: time.value, 
               target: timer, 
               paused: !time.start, 
               toggle: handleToggleState,
               play: handlePlay,
               pause: handlePause,
               init: handleInit
            });
      }
    return (() => { if(timer) window.clearTimeout(timer); });
   });

   return (
        <Typography {...({variant:"h5",...otherProps}) }>
             {
                 (() => {
                        if(time.value instanceof Date) 
                           return time.value.toString().slice(16, 24);
                        else 
                           return time.value;
                 })()
             }
         </Typography>
    )
}

export function Lang() {

    const { languages, local, actions } = useData();
    const [currentLang] = useState(local.lang);

    const handleChangeLang = (event, value) => {
        const lang = value.props.value
     actions.handleChangeGlobalProp('local', {...local, 'lang': lang});

    }
    const langs = Object.keys(languages).map((lang, index) => {
        return(
            <MenuItem 
                value={lang} 
                disabled={'en-EN' === lang}
                key={index} 
                selected={lang === local.lang} 
                size="small">
                {languages[lang].title}
            </MenuItem>
        )
    });

    return (
        <Box>
            <Typography color="text.secondary" variant="h6">Langue</Typography>
            <Select 
                fullWidth
                spacing={1} 
                component={Grid}
                value={currentLang}
                size="small"
                onChange={handleChangeLang}
                
            >{langs}</Select>
        </Box>
    );
}

export function Themes() {

    const { local, actions } = useData();
    const [currentTheme, setCurrentTheme] = useState(local.theme)
    
    const handleChangeTheme =  (event, theme) => {
        setCurrentTheme(theme);
        actions.handleTheme(theme);
    }
    const themes = [
        { title: 'light', icon: WbSunnyIcon }, 
        { title: 'dark', icon: ModeNightIcon },
        { title: 'system', icon: ComputerIcon }
    ].map((theme, index) => {
        const Icon = theme.icon;
        return(
            <ToggleButton disabled={currentTheme === theme.title} value={theme.title} key={index}>
                <Icon/>
            </ToggleButton>
        )
    });

    return (
        <Box>
            <Typography color="text.secondary" variant="h6">Theme</Typography>
            <ToggleButtonGroup 
                onChange={handleChangeTheme}
                value={currentTheme}
                exclusive
                color="primary"
                fullWidth
                size="small"
            >{themes}</ToggleButtonGroup>
        </Box>
    );
}

export function ProfileNav(props) {

    const [value, action] = useSetting();
    const [currentSession, setCurrentSession] = useContext(CurrentSession); 
    const open = Boolean(value.profileNav);
    //const { text } = useData();
    const redirectTo = useNavigate();
    const [file, setFile] = useState(null);
    const fileField = useRef();
    const handleRedirect = () => {
        localStorageData.del('session');
        action.onClose('profileNav')();
        setCurrentSession(null);
        redirectTo('/');
    }

    const handleChangeFile = (event) => {
        const targetFile = event.target.files[0];
        if(targetFile)
            setFile(targetFile)
    };
    const handleGetLocalFile = () => {
        fileField.current.click();
    };

    return ( currentSession && currentSession.token &&
        <Menu
            anchorEl={value.profileNav}
            open={open}
            onClose={action.onClose('profileNav')}
        >
            <input onChange={handleChangeFile} hidden type="file" accept="image/*" ref={fileField} />
            {file && 
            <AvatarEditor 
                file={file} 
                onCancel={() => {
                    setFile(null);
                }} 
            />}
            <Box
                sx={{position: 'relative', m:1, width: 300}}
            >
                <Box sx={{ textAlign: 'center'}}>
                <Badge
                    overlap="circular"
                    
                    anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                    badgeContent={
                        <Box sx={{ bgcolor: 'background.paper', borderRadius: 50}}>
                            <IconButton
                                size="small"
                                onClick={handleGetLocalFile}
                            >
                                <AddAPhotoIcon sx={{ fontSize: 18}}/>
                            </IconButton>
                        </Box>
                    }
                >
                        <Box 
                            component={Avatar} 
                            sx={{
                                height: 60,
                                width: 60,
                                m: 'auto',
                                bgcolor: 'primary.main',
                                fontSize: 40
                            }}
                            children={currentSession.lastName.charAt(0)}
                        />
                    </Badge>
                        <Box>
                            <Typography
                                    children={currentSession.lastName + ' ' + currentSession.firstName}
                                    align="center"
                            />
                            <Typography
                                children={currentSession.email}
                                color="text.secondary"
                                align="center"
                            />
                        </Box>
                        <Box sx={{mt:2.5, mb:2.5, textAlign:'center'}}>
                            <Button
                                children="gerer votre compte"
                                variant="outlined"
                                size="small"
                            />
                        </Box>
                        <Divider/>
                    
                        <Box sx={{mt:2, mb:2, textAlign: 'center'}}>
                            <Button
                                children="deconnexion"
                                size="small"
                                variant="contained"
                                onClick={handleRedirect}
                            /> 
                        </Box>

                        <Divider/>
                        <Box sx={{pt:1 ,textAlign: 'center', flexDirection: 'row', display: 'flex'}}>
                            <Box sx={{flexGrow: 1, display: 'flex'}}>
                                <Typography variant="caption" color="text.secondary">
                                    Règles de confidentialité
                                </Typography>
                            </Box>
                            <Box sx={{flexGrow: 1, display: 'flex'}}>
                            <Typography variant="caption" color="text.secondary">
                                    Conditions d'utilisation
                                </Typography>
                            </Box>
                        </Box>
                </Box>
            </Box>
        </Menu>
        );
    
}