import { Box,  Typography, Button, Slider, IconButton, LinearProgress, Modal } from '@mui/material';
import { forwardRef, useContext, useEffect, useRef, useState } from 'react';
import CropRotateIcon from '@mui/icons-material/CropRotate';
import * as PictureEditor from 'react-avatar-editor';
import axios from 'axios';
import { getFileName } from '../treatments/getFileExtension';
import { CurrentSession } from './Auth';
import serverPath from '../treatments/severPath';

function AvatarEditor(props) {
    const [values, setValues] = useState({
        file: props.file,
        url: null
    });
    const [currentSession] = useContext(CurrentSession);
    const fileFieldRef = useRef();

    const handleSendFile = () => {
    if(values.url)
       axios({
           method: 'get',
           responseType: 'blob',
           url: fileFieldRef.current.getImage().toDataURL()
       }).then((result) => {
            const createFile = new File(
                [result.data],
                getFileName(values.file.name) + '.png',
                {type: 'image/png'});

            const route = serverPath('');
            const formData = new FormData();
            formData.append('file', createFile);

            axios({
                headers: {
                    'Authorization': `Bearer ${currentSession.token}`
                 },
                 method: 'post',
                 url: route,
                 data: formData
             }).then((result) => { }).catch((error) => {})
       })
    }
    useEffect(() => {
       const fileReader = new FileReader(values.file);
       fileReader.onload = () => {
            setValues({...values, url: fileReader.result})
       };
       fileReader.readAsDataURL(values.file)
    },[values.file]);

    return (
        <Modal
            open={Boolean(values.file)}
        >
            <Box 
                sx={{
                    //width:550,
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    position: 'relative',
                    width: 600,
                    bgcolor: 'background.paper',
                    p:1
                }}
            >
                <Box sx={{display: 'flex', alignContent: 'center'}}>
                    {values.url ? (
                    <PictureEditorFrame url={values.url} ref={fileFieldRef}/>): 
                    <Box sx={{
                        height: 250
                    }}>
                        <LinearProgress   sx={{
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)',
                            position: 'relative'
                    }}/>
                    </Box>
                    }
                </Box>
                <Box sx={{display: 'relative'}}>
                    <Box sx={{display: 'flex'}}>
                        <Box sx={{flexGrow: 1, textAlign: 'center'}}>
                            <Button
                                children="annuler"
                                onClick={props.onCancel}
                                size="small"
                                disabled={!values.url}
                            />
                        </Box>
                        <Box sx={{flexGrow: 1, textAlign: 'center'}}>
                            <Button
                                children="ajouter"
                                variant="contained"
                                size="small"
                                disabled={!values.url}
                                onClick={handleSendFile}
                            />
                        </Box>
                    </Box>
                </Box>
            </Box>
        </Modal>
    )
}

const PictureEditorFrame = forwardRef((props, ref) => {

    const [values, setValues] = useState({
        zoom: 1,
        rotate: 0
    });

    return(
        <Box sx={{flexGrow: 1}}>
            <Box 
                component={PictureEditor}
                image={props.url}
                scale={values.zoom}
                sx={{
                    bgcolor: 'primary.main',
                    m: 'auto',
                    display: 'block'
                }}
                rotate={values.rotate}
                ref={ref}
                scale={values.zoom}
            />
            <Box>
                <Box>  
                    <Typography color="primary">
                        zoom
                    </Typography> 
                    <Slider 
                        aria-label="zoom"
                        min={1} 
                        max={5}
                        value={values.zoom} 
                        onChange={(event, value) => {
                            setValues({...values, zoom: value})
                        }}
                        step={.01} 
                        size="small"
                    />
                </Box>
                <Box>
                    <Typography  color="primary">
                        Rotation
                    </Typography>
                    <IconButton
                        onClick={(event) => {
                            setValues({...values, rotate: values.rotate + 90})
                        }} 
                    >
                        <CropRotateIcon/> 
                    </IconButton>
                </Box>
            </Box>
        </Box>
    )
})
export default AvatarEditor