import { Box, Divider, Typography, useMediaQuery } from '@mui/material';
import { useData } from '../treatments/globalData';
import GeidLogo from './GeidLogo';

function PageNotFound() {
    const { screen } = useData();
    const isMiddleScreen = useMediaQuery(screen);

    return (
        <Box sx={{textAlign: 'center'}}>
            <GeidLogo fontSize={isMiddleScreen ? 200 : 80}/>
            <Divider>
                <Typography color="text.secondary" variant="h4" > 404 page not found</Typography>
            </Divider>
        </Box>
    );
}

export default PageNotFound;