import * as url from 'url';
function serverPath(childRoute) {
	let route = String(childRoute || '');
	route = route.charAt(0) === '/' ? route : (route.trim() ? '/' + route : route);
	const protocol = '';
	const serverUrl = '';
	const port = 3000;

	return (`${protocol.trim() === '' ? url.parse(String(window.location)).protocol : protocol }//${ serverUrl.trim() === '' ? url.parse(String(window.location)).host.split(':')[0] : serverUrl.trim().split(':')[0]}:${port}${route}`)
}
export default serverPath;