const UserInfos = createContext({});

const useUserInfo = () => {
    const { text } = useData();
    const [values, setValues ] = useState({
        error: null,
        lastName: useRef(),
        firstName: useRef(),
        middleName: useRef(),
        function: useRef(),
        grade: useRef(),
        phoneNumber: useRef(),
        email: useRef(),
        password: useRef(),
        loading: true,
        data: null,
        code: randomCode(),
        timer : null,
        checked: false,
        step: 0,
        session: true,
        steps: [
            {
                label: 'Information Personnelle', 
                icon: AdminPanelSettingsIcon,
                fields: ['lastName', 'firstName', 'function', 'grade' ],
                treatment: PersonalIdentity,
                describe: ''
            },
            {
                label: 'Information du compte', 
                icon: ManageAccountsIcon, 
                fields: ['email', 'phoneNumber', 'password'],
                treatment: AccountIdentity,
                describe: ''  
            },
            {
                label: 'Validation du compte', 
                icon: HowToRegIcon, 
                treatment: ValidateIdentity,
                describe: ''
            }
        ]
      .map((obj, index) => ({...obj, ...text.home.signup.steps[index]}))
    });
    const staticActions = {
        checkAdress(code, update=true) {
            const route  = serverPath('api/auth/validate');
            const validateInfos = {
                email: values.email.current, 
				key: code || values.code 
            };

            axios.post(route, validateInfos).then((result) => {
                if(result.data && update) {
                    setValues({
                        ...values,
                        loading: false,
                    })
                }
            }).catch((error) => {
                //const serverResponse = error.response;
                setValues({
                    ...values,
                    loading: false,
                    error: 'system'// serverResponse ? serverResponse : 'system',
                })
            });
        },
    };
    const actions = {
        ...staticActions,
        handleChangeValues(prop, value) {
           setValues({...values, ...(
               (typeof prop === 'string') ? {
                   [prop]: value
               } : {...prop}
           )})
        },
        next(treat=true) {
            const step = values.step;
            if(treat) {
                const fields = values.steps[step].fields || [];
                let error = false;
                fields.forEach((field) => {
                    if(!values[field].current)
                        error = true
                });
                
                setValues({...values, ...( error ? {
                    checked: true
                } : {
                    step: step < 2 ? (step + 1) : step,
                    loading: step === 1,
                    checked: false,
                    error: null
                })});
            } else {
                setValues({...values, step: step + 1});
            }
        },
        previous() {
            setValues({
                ...values, 
                step: values.step - 1, 
                error: null, 
                code: randomCode()
            });
        },
        getStructure() {
            const route  = serverPath('api/auth/init');
            axios.get(route).then((result) => {
              
                if(result.data) {
                    setValues({
                        ...values,
                        loading: false,
                        data: result.data
                    })
                }
            }).catch((error) => {

                const serverResponse = error.response.error;
            
                setValues({
                    ...values,
                    loading: false,
                    error: serverResponse ? serverResponse.toString() : 'system',
                })
            });
        },
       
        generateCode() {
          const code = randomCode();
          setValues({...values, code: code});
          return code;
        },
        handleClickRetray() {
            const code = randomCode();
            setValues({...values, timer : null, code: code});
            if(Boolean(values.timer)) {
                values.timer.init();
                staticActions.checkAdress(code, false);
               }
        }
    };
    return [values, actions];
}

function SignUp () {
    const { screen, text, local } = useData();
    const isMiddleScreen = useMediaQuery(screen);
    const user = useUserInfo();
    const [values, actions] =  user;
    const [, action] = useSetting();
    const Treat = values.steps[values.step] ? values.steps[values.step].treatment : Navigate;
 
    useEffect(()=> {
    const controller = new AbortController();
      const isData = Boolean(values.data);
      if(values.loading && !isData) actions.getStructure();
        return (() => {
            controller.abort();
        })
    },[values.data, values.loading, actions]);

    useEffect(() => {
        const controller = new AbortController();
        if(values.loading  && values.step === 2) actions.checkAdress();
        return (() => {
            controller.abort();
        })
    },[actions, values.step, values.loading]);
     
    return( 
        <UserInfos.Provider value={user}>
            <AppContentBox>
                <AppHeader
                    icon={<GeidLogo/>}
                >
                    <Box
                        sx={{flexGrow: 1}}
                    />
                    <Tooltip arrow title={'paramètre'}>
                        <IconButton 
                            onClick={action.onOpen('settingOptions')}
                        >
                            <SettingsIcon/>
                        </IconButton>
                    </Tooltip>
                </AppHeader>
                <Content>
                    <Box container component={Grid}>
                        <Grid sx={{p: isMiddleScreen ? 1 : 0}} item md={7} xs={12}>
                            <Box component={ isMiddleScreen ? Card : 'div'}>
                                <Box 
                                    component={CardHeader}
                                    title={<Typography color="primary" variant="h6" >{capStr(text.home.signup.title)}</Typography>}
                                >
                                    
                                </Box>

                                {!isMiddleScreen && <StepperLevel steps={values.steps} step={values.step}/> }
                                <Box sx={{height: isMiddleScreen ? 210: ''}} component={CardContent}>
                                {/* content*/}
                                { Boolean(values.data && !values.loading && values.error === null) ? 
                                (<Treat to={values.session ? '/home' : "/"} />) : (
                                    <Box sx={{ 
                                        display: 'flex',
                                        flexDirection: 'column',
                                        alignItems: 'center',
                                        m:5
                                    }}>
                                        {values.loading && <CircularProgress />}
                                        {values.error &&  
                                        <Alert severity="error">
                                            <AlertTitle>{capStr(text.server.error.title)}</AlertTitle>
                                            {values.error === 'system' ?
                                            (<Fragment>
                                                {capStr(text.server.error.content)}.<br/>
                                                <Link to="/home/signup">{capStr(text.server.error.link)}</Link>
                                            </Fragment>) : 
                                            capStr(text.input.error[values.error].found)
                                            }

                                        </Alert>
                                        }
                                        
                                    </Box>
                                )
                                }
                                </Box>
                                <Box component={CardActions}>
                                    <Box sx={{flexGrow:1, textAlign: 'left'}}>
                                        {values.step === 0 ? 
                                        (<Button size="small" to="/home/login" LinkComponent={Link}>{text.home.signup.button.back}</Button>):
                                        (<Button size="small" disabled={values.loading} onClick={actions.previous} variant="outlined">{text.home.signup.button.previous}</Button>)}
                                    </Box>
                                    <Box sx={{flexGrow:1, textAlign: 'right'}}>
                                        {values.step < 2 && 
                                        <Button 
                                            onClick={actions.next} 
                                            variant="contained"
                                            size="small"
                                        >{text.home.signup.button.next}</Button>}
                                        
                                        {values.step === 2 && 
                                        <Button 
                                            onClick={actions.handleClickRetray} 
                                            disabled={!Boolean(values.timer) || Boolean(values.error)} 
                                            variant="outlined"
                                            size="small"
                                        >{text.home.signup.validate.retry}</Button>}
                                    </Box>
                                </Box>
                            </Box>
                            <Box sx={{textAlign: 'center', pt:1}}>
                                <Box component={ isMiddleScreen ? Toolbar : 'div'} sx={{"&>*":{m:1}}}>
                                    <Box 
                                    {...(
                                        isMiddleScreen ? 
                                        {
                                            component: 'span',
                                            sx:{
                                            "&>*": {
                                                ml: 1
                                            }
                                            }
                                        } : {
                                            component: 'div',
                                            sx:{
                                                flexDirection: 'row',
                                                alignItems: 'center',
                                                "&>*": {
                                                    ml: 1
                                                }
                                            }
                                        }
                                    )}
                                    
                                    >
                                            <Avatar
                                                sx={{display: 'inline-block'}} 
                                                src={require('../assets/rdc.png')}
                                            />
                                            <Avatar 
                                                sx={{display: 'inline-block'}} 
                                                src={require('../assets/budget.jpg')}
                                            />
                                            <Avatar 
                                                sx={{display: 'inline-block'}} 
                                                src={require('../assets/dantic_1.jpg')}
                                            />
                                    </Box>
                                    <Typography color="text.secondary" align="center" variant="caption">
                                        DANTIC
                                        &copy; {(new Date())
                                        .toLocaleDateString(local.lang,
                                        { weekday: 'long', 
                                        year: 'numeric', 
                                        month: 'long', 
                                        day: 'numeric' 
                                        }).toString()}
                                    </Typography>
                                </Box>
                            </Box>
                        </Grid>
                    {isMiddleScreen && 
                        <Grid sx={{p: 1}} item md={5}>
                            <StepperLevel steps={values.steps} step={values.step}/>
                        </Grid>}
                    </Box>
                </Content>
            </AppContentBox>
        </UserInfos.Provider>
    )
}

function PersonalIdentity() {
    const { screen, text } = useData();
    const isMiddleScreen = useMediaQuery(screen);
    const [values] = useContext(UserInfos);
    const [fieldLevel, setFieldLevel] = useState(null);
    const funcFields = Object.keys(values.data).map((func) => ({title: func, value: func }));
    const secteurFields = Boolean(fieldLevel) ? values.data[fieldLevel]
    .map((secteur) => ({title: secteur, value: secteur })) : [];
    
    const handleChange = (event) =>  {
        if(funcFields[0].value === event.target.value) {
            values.grade.current = values.data[event.target.value];
            setFieldLevel(null);
        }
        else setFieldLevel(event.target.value)
        
    }

    return (
        <Box spacing={isMiddleScreen ? 1 : 2} container component={Grid}>
            <Box xs={12} md={4} item component={Grid}>
                <FieldController
                    type="text"
                    regExp={regExpBase.name}
                    label={capStr(text.input.label.name)}
                    checking={values.checked}
                    helperTextError={capStr(text.input.error.format)}
                    icon={true}
                    value={values.lastName.current}
                    ref={values.lastName}
                    fullWidth
                    size="small"
                />
            </Box>
            <Box xs={12} md={4} item component={Grid}>
                <FieldController
                     type="text"
                     regExp={regExpBase.name}
                     label={capStr(text.input.label.middleName)}
                     checking={values.checked}
                     helperTextError={capStr(text.input.error.format)}
                     icon={true}
                     value={values.middleName.current}
                     ref={values.middleName}
                     fullWidth
                     size="small"
                />
            </Box>
            <Box xs={12} md={4} item component={Grid}>
                <FieldController
                    type="text"
                    regExp={regExpBase.name}
                    label={capStr(text.input.label.firstName)}
                    checking={values.checked}
                    helperTextError={capStr(text.input.error.format)}
                    ref={values.firstName}
                    value={values.firstName.current}
                    icon={true}
                    size="small"
                    fullWidth
                />
                
            </Box>
            <Box sx={isMiddleScreen ? {pl:1, pr:1} : {pl:2, pr:2}}>
                <FormHelperText>{capStr(text.input.error.name.help)}</FormHelperText>
            </Box>
            <Box sx={{mt: isMiddleScreen ? 2 : 0}} xs={12} md={6} item component={Grid}>
                <SelectList
                    label="fonction"
                    items={funcFields}
                    checking={values.checked}
                    value={values.function.current}
                    ref={values.function}
                    fullWidth
                    onChange={handleChange}
                    size="small"
                />
                
            </Box>
            <Box sx={{mt: isMiddleScreen ? 2 : 0}} xs={12} md={6} item component={Grid}>
                <SelectList
                    label="secteur"
                    items={secteurFields}
                    checking={Boolean(secteurFields.length) && values.checked} 
                    disabled={!Boolean(secteurFields.length)}
                    value={values.grade.current}
                    ref={values.grade}
                    size="small"
                    fullWidth
                />
                
            </Box>
        </Box>
    );
}

