const PasswordField = forwardRef((props, ref) => {
   const { screen, text } = useData();
   const isMiddleScreen = useMediaQuery(screen);
   const [values] = useContext(UserInfos);
   const [password, setPassword] = useState({showPassword: false, value:''});
   
   const handleChangeValue = (event) => {
     setPassword({...password, value: event.target.value})
   };
   
   const handleChangeShowPassword = (event) => {
      setPassword({...password, showPassword: !password.showPassword})
   };
   
   return (
      <Fragment>
         <Box sx={{mt: isMiddleScreen ? 2 : 0}} xs={12} md={6} item component={Grid}>
             <FieldController
                 type="password"
                 regExp={regExpBase.password}
                 label={capStr(text.input.label.create.password)}
                 checking={values.checked}
                 helperTextError={capStr(text.input.error.format)}
                 icon={true}
                 onChange={handleChangeValue}
                 showPassword={password.showPassword}
                 onShowPassword={handleChangeShowPassword}
                 size="small"
                 fullWidth
             />
             
         </Box>
         <Box sx={{mt: isMiddleScreen ? 2 : 0}} xs={12} md={6} item component={Grid}>
             <FieldController
                 type="password"
                 regExp={`^${password.value === '' ? '.{100,100}' : password.value }$`}
                 label={capStr(text.input.label.create.confirm)}
                 checking={values.checked}
                 helperTextError={capStr(text.input.error.format)}
                 ref={ref}
                 showPassword={password.showPassword}
                 onShowPassword={handleChangeShowPassword}
                 icon={true}
                 size="small"
                 fullWidth
             />
             
         </Box>
      </Fragment>
      )
});

function ValidateIdentity() {
    const {text, local, screen} = useData();
    const [values, actions] = useContext(UserInfos);
    const [error, setError] = useState(null);
    const [, setSession] = useContext(CurrentSession);
    const [connectionOption, setConnectionOption] = useState("connected");
    const isMiddleScreen = useMediaQuery(screen);
    const redirect = useNavigate();
    
    const handleChangeOption = (event, value) => {
        setConnectionOption(value);
        if(value === 'none')
            actions.handleChangeValues({...values, session: false});
        else
            actions.handleChangeValues({...values, session: true});
            
    }

    const handlekeyCode = (code) => { 
        if(code === values.code && values.loading === false)  {
            setError(false);
            actions.handleChangeValues('loading', true);
            handleSignUp();
        }
        else setError(true)

    }

    const handleTimer = (event) => {
        event.pause();
        actions.handleChangeValues('timer', event);
    }
    
    console.log('user',{
        fname : values.firstName.current, 
        lname: values.lastName.current, 
        mname: values.middleName.current, 
        email: values.email.current, 
        phoneCell: values.phoneNumber.current, 
        password: values.password.current,  
        grade: {
            grade : values.function.current,
            role : values.grade.current
        }
    });

    const handleLogIn = (email, password, connectionOption) => {
        if(email && password) {
            const route = serverPath('api/auth/login');
            axios.post(route,{
                email: email,
                password: password
            }).then((result) => {
                if(result.data) {
                    const user = {
                        token: result.data.token,
                        firstName: result.data.userFname,
                        lastName: result.data.userLname,
                        middleName: result.data.userMname,
                        email: result.data.userEmail,
                        grade: result.data.userGrade,
                        password: password,
                        id: result.data.userId,
                        geidConfig: {
                            docTypes: result.data.docTypes,
                            permission: result.data.userGrade.permission
                        }
                    };

                    if(connectionOption !== "none" ) {
                        localStorageData.set("session", user);
                        if(connectionOption === "stayed")
                            localStorageData.set("local", {...local, cookie: user});    
                    } 
                    setSession(user);
                    redirect('/');
                }
            }).catch((error) => {
                //console.log(error.toString());
                //const message = error.response ? error.response.data.error : 'system';
                console.log(error.toString());
                //setValues({...values, loading: false, error: message});

            })
           
        } else {
            console.log('private error');
            //setValues({...values, error: "system"});
        }
    }

    const handleSignUp = () => {
        const route = serverPath('api/auth/signup');
        const userInfos = {
            fname : values.firstName.current, 
            lname: values.lastName.current, 
            mname: values.middleName.current, 
            email: values.email.current, 
            phoneCell: values.phoneNumber.current, 
            password: values.password.current,  
            grade: {
                grade : values.function.current,
                role : values.grade.current
            }
        };
        axios({
            method: 'post',
            url: route,
            data: userInfos,
            headers: {'Content-Type': 'application/json;charset=utf-8'}
        }).then((result) => {
            if(result.data) {
                const user = {
                    pass: values.password.current,
                    email: values.email.current,
                };
                handleLogIn(user.email, user.pass, connectionOption);
            }
        }).catch((error) => {
           let type = null;
           if(error.response)
            ['grade.role', 'email', 'phoneCell'].forEach((typeError) => {
                    if(error.response.data.error.errors[typeError] && type === null)
                        type = typeError === 'grade.role' ? 'grade' : (typeError === 'phoneCell' ? 'number' : typeError);
            });
    
           actions.handleChangeValues({
               ...values,
               error: type || 'system',
               loading: false
           });
            
        })
    }

    return (
        <Box>
            <Typography>
               {text.home.signup.validate.content}
            </Typography>
            <Typography color="primary">
               {values.email.current} {text.home.signup.validate.find} <Timer action={handleTimer} reverse={true} min={0} max={30} component="span" variant="string"/>s
            </Typography>
            <Box sx={{pt:2, position: 'relative'}}>
                <CodeField
                    action={handlekeyCode}
                />
                {error && <Typography paragraph {...(isMiddleScreen ? {
                    position:'absolute',
                    sx:{ width: '100%'}
                } : {})}   variant="caption" align="center" color="error">{text.input.error.code}</Typography>}
            </Box>
            <Box 
            >
                <FormControl>
                    <FormLabel >Options àpres l'inscription</FormLabel>
                    <RadioGroup
                        row
                        value={connectionOption}
                        onChange={handleChangeOption}
                    >
                        <FormControlLabel value="connected" control={<Radio />} label="Connectez-vous" />
                        <FormControlLabel value="stayed" control={<Radio />} label="Restez connecté" />
                        <FormControlLabel value="none" control={<Radio />} label="Restez deconnecté"/>
                    </RadioGroup>
                </FormControl>
            </Box>
        </Box>
    );
}
