import { ThemeProvider, createTheme, styled } from '@mui/material';
import { useLayoutEffect } from 'react';
import { useData} from '../treatments/globalData';
import useSystemTheme from '../treatments/useSytemTheme';

function Theme({children}) {
        const { themes, local } = useData();
        const systemTheme = useSystemTheme();
        const currentTheme = local.theme === 'system' ? 
        systemTheme : local.theme;
        const theme = createTheme(themes[currentTheme]);

        useLayoutEffect(()=> {
            document.body.style.backgroundColor = theme.palette.background.default;
            document.body.style.color = theme.palette.mode === 'dark' ?
            theme.palette.primary.contrastText : null;
            [...document.head.getElementsByTagName('meta')].forEach(
              (element) => {
                if(element.name === 'theme-color')
                  element.content = theme.palette.primary.main ;
              });
          });
    return (
            <ThemeProvider
                theme={theme}
            > 
            <div>
                {children}
            </div>
            </ThemeProvider>
    );

}
export default Theme;