import { 
    Box, 
    useTheme, 
    Typography, 
    List, 
    ListSubheader, 
    ListItemIcon, 
    ListItemButton, 
    ListItemText, 
    useMediaQuery, 
    Grid,
    Avatar,
    Toolbar,
    Divider
} from "@mui/material";
import { useData } from "../treatments/globalData";
import { Fragment } from 'react';
import LinkIcon from '@mui/icons-material/Link';

const dateConfig = { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
};

function Footer(props) {
    const { local, links, screen } = useData();
    const theme = useTheme();
    const isMiddleScreen = useMediaQuery(screen);
    const bgcolor = theme.palette.primary.main;
  
    return(
        <Fragment>
            <Box 
                sx={{ mt: .1, pt:5, pb:5}} 
                bgcolor={bgcolor} 
                { ...( isMiddleScreen ? { 
                    component: Grid,
                    container: true,
                    spacing: 1
                } : {})}
            >
                <Box { ...( isMiddleScreen ? { 
                    component: Grid,
                    item: true
                } : {})}>
                    <List
                        component="nav"
                        sx={{ '& *':{color: '#fff'}, bgcolor: 'background.primary' }}
                        subheader={
                            <ListSubheader sx={{bgcolor:'transparent',...theme.typography.h6, color: '#fff' }} component="div" >
                                Liens connexes
                            </ListSubheader>
                        }
                    >
                        {
                            links.map((link, index) => Boolean(link.href) && (
                                <ListItemButton 
                                    key={index} 
                                    href={link.href} 
                                    component="a"
                                    target="_blank"
                                    size="small"
                                    sx={{ py: 0, minHeight: 32, color: 'rgba(255,255,255,.8)' }}
                                >
                                    <ListItemIcon>
                                         <LinkIcon />
                                    </ListItemIcon>
                                    <ListItemText  primary={link.title}/>
                                </ListItemButton>
                            ))
                        }
                    </List>
                </Box>
                {isMiddleScreen && 
                <Grid item>
                        ...
                </Grid>}
            </Box>
            
            <Box
                sx={{
                    textAlign: 'center'
                }}
            >
                <Box sx={{p:1}}>
                    <Divider>
                        <Toolbar sx={{
                            '&>*': isMiddleScreen ? 
                            { height:100, width:100, m:1} : 
                            {height: 110, width: 110, m:1},
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center'
                        }}>
                            <Avatar
                                src={require('../assets/rdc.png')}
                            />
                            <Avatar
                                src={require('../assets/budget.jpg')}
                            />
                            <Avatar
                                src={require('../assets/logodantic.png')}
                            />
                        </Toolbar>
                    </Divider>
                </Box>
                <Typography color="text.secondary" align="center" variant="caption">
                  DIRECTION ARCHIVES ET NOUVELLES TECHNOLOGIE DE L'INFORMATION ET DE LA COMMUNICTATION
                &copy; {(new Date()).toLocaleDateString(local.lang, dateConfig).toString()}
                </Typography>  
            </Box>

        </Fragment>
    );
}
export default Footer;