import React, { useLayoutEffect } from 'react';
import { useTheme } from '@mui/material/styles'
import './styles/App.css';
import  './styles/scrollbar.css';
import './styles/book.css'
import Auth from './components/Auth';
import { DataProvider, useGlobalState } from './treatments/globalData';
import config from './config/config.json';

function App() {
    const [globalData, actions] = useGlobalState();
    const values = {
      ...globalData, 
      actions : actions, 
      text: require('./config/' + config.lang[globalData.local.lang].path),
      languages: config.lang,
      screen: useTheme().breakpoints.up('md'),
      onglets: config.app.onglets,
      themes: config.user.theme,
      frameApps: config.frameApp,
      links: config.links,
      documents: config.documents,
      applications: config.app.applications
    };
    
    useLayoutEffect(()=> {
      document.documentElement.lang = values.lang;
    })
  
  return (
      <DataProvider value={values}>
          <Auth/>
      </DataProvider>
  );
}
export default App;