import { 
  BrowserRouter,
  Routes,
  Route, 
  Navigate 
} from 'react-router-dom';
import { SettingProvider, useSettingTreatment } from '../treatments/globalData';
import Test from '../test/Test';
import Home from '../main/Home';
import PageNotFound from './PageNotFound';
import Header from './Header';

import MediaLibrary from '../apps/medialibrary/MediaLibrary';
import Archive from '../apps/archive/Archive';
import WorkSpace from '../apps/workspace/WorkSpace';

import Theme from './Theme';
import * as localStorageData from '../treatments/localStorageData';
import SignUp from '../main/signUp';
import { createContext, useState } from 'react';
import SettingsGlobal from './SettingsGlobal';
import Censorship from '../apps/censorship/Censorship';
import Dashboard from '../apps/dashboard/Dashboard';
import Note from '../apps/Note/Note';

export const CurrentSession = createContext(null);

const SessionProvider = CurrentSession.Provider;

function Auth() {
  const { local, session } = localStorageData.get();
  const [currentSession, setSession] = useState(local.cookie || session);
  const authenticate = Boolean(currentSession);
  const route = authenticate ? 'home' : 'home/login';

  const settingApp = useSettingTreatment();

    return (
      <Theme>
        <SessionProvider value={[currentSession, setSession]}>
          <SettingProvider value={settingApp}>
                <BrowserRouter>
                  <SettingsGlobal />
                  <Header/>
                  <Routes>
                    <Route exact path="/" element={<Navigate to={route}/>} />
                    <Route path={route} element={<Home/>} />
                    {
                      authenticate ? (
                        <Route>
                          <Route path="/apps/archive" element={<Archive/>} />
                          <Route path="/apps/workspace" element={<WorkSpace/>} />
                          <Route path="/apps/dashboard" element={<Dashboard/>} />
                          <Route path="/apps/note" element={<Note/>} />
                        </Route> 
                      ) : 
                      ( /*les routes public */
                        <Route path="/home/signUp" element={<SignUp/>}/> 
                      )
                    }
                    <Route path="*" element={<PageNotFound/>} />
                    <Route path="/medialibrary" element={<Navigate to="/apps/medialibrary"/>} />
                    <Route path="/test" element={<Test/>} />
                    {
                      ';pictures;films;books;censor'.split(';').map((subRoute, index)=>
                      (<Route 
                        key={index}
                        path={`/apps/medialibrary${ Boolean(subRoute) ? '/'+ subRoute : ''}`} 
                        element={ Boolean(subRoute) ? <MediaLibrary/> : <Navigate to="/apps/medialibrary/books"/> } 
                      />))
                    }

                    {
                      ';archives;mediatheque'.split(';').map((subRoute, index)=>
                      (<Route 
                        key={index}
                        path={`/apps/censorship${ Boolean(subRoute) ? '/'+ subRoute : ''}`} 
                        element={ <Censorship/> } 
                      />))
                    }

                  </Routes>
              </BrowserRouter>
            </SettingProvider>
          </SessionProvider>
      </Theme>
    );
};

export default Auth;