import {Fragment, useState} from 'react';
import {
  ButtonBase, 
  Box,
  Stepper,
  Step,
  StepLabel,
  StepContent,
  Typography,
  Button
} from '@mui/material';
import CheckIcon from "@mui/icons-material/Check";
import { useData } from '../treatments/globalData';
import { useMediaQuery, IconButton, Modal } from '@mui/material';
import capStr from '../treatments/capStr';

function StepperLevel(props) {
  const { steps, step:activeStep } = props;
  const { screen } = useData();
  const isMiddleScreen = useMediaQuery(screen);
  const [modalInfos, setModalInfos] = useState({
    open: false,
    label: "",
    describe: "",
  });

  const handleModal = (infos) => () => {
    setModalInfos(Boolean(infos) ? {
      open: true,
      label: infos.label,
      describe: infos.describe,
      icon: infos.icon
    } : {
    open: false,
    label: "",
    describe: "",
    icon: null,
    })
  };
  return (
    <Fragment>
        <Box>
          <Stepper activeStep={activeStep} orientation={ isMiddleScreen ? 'vertical' : 'horizontal' }>
            {steps.map((step, index) => (isMiddleScreen || index === activeStep ) && (
              <Step sx={{
                fontSize:"50px",
                color: activeStep >= index ? "primary.main" : 'text.secondary'
              }} key={step.label}>
                <StepLabel 
                  onClick={isMiddleScreen ? null : handleModal(step)}
                  icon={
                    <step.icon  
                      sx={{
                        fontSize:"50px",
                        color: activeStep >= index ? "primary.main" : 'text.secondary'
                      }}
                    />
                  }>
                  <Box component={ isMiddleScreen ? 'span' :  ButtonBase }>
                    {capStr(step.label)}{index < activeStep && <CheckIcon  sx={{color: "primary.main"}}/>}
                  </Box>
                  </StepLabel>
              {isMiddleScreen && 
              <StepContent>
                  <Typography variant="body2">{capStr(step.describe)}</Typography>
                </StepContent>}
              </Step>
            ))}
          </Stepper>
        </Box>
        <Modal
            open={modalInfos.open}
            onClose={handleModal(null)}
          >
            <Box
              sx={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              width: 345,
              bgcolor: 'background.paper',
              boxShadow: 24,
              p: 2,
              "& > *": {
              mb:1
              }
            }}
            >
              <Typography color="primary" variant="h5">
                {modalInfos.icon &&
                  (<modalInfos.icon
                    sx={{fontSize: '2em'}}
                  />)
                }
                <Box sx={{position: 'relative', top: -15}} component="span">{capStr(modalInfos.label)}</Box>
              </Typography>
              <Typography variant="body2" >{capStr(modalInfos.describe)}</Typography>
              <Button 
                variant="contained"
                onClick={handleModal(null)}
                sx={{mt:1}}
                fullWidth
              >OK</Button>
            </Box>
          </Modal>
    </Fragment>
  );
}

export default  StepperLevel;