import { Box, Chip, duration, Grid, Skeleton, useTheme } from "@mui/material";
import { Fragment, useEffect, useRef, useState } from "react"
import { Link } from "react-router-dom";
import formatTimer from "../treatments/formatTimer";

function Video(props) {
    const video = useRef();
    const [values, setValues] = useState({
        load: false,
        duration: 0,
        enter: null,
        timer: null,
    })
    const [currentTime, setCurrentTime] = useState(0);

    const theme = useTheme();
    const { playBackRate, ...otherProps } = props;
    const handleLoad = (event) => {
       setValues({...values, load: true, duration: event.target.duration});
    }
    const handleMouse = (event) => {
        if(video.current.paused) {
            video.current.play();
            setValues({...values, enter : true})
        }
        else {
            video.current.currentTime = 0;
            video.current.pause();
            setValues({...values, enter : false})
        }
    };

    useEffect(() => {
        let timer = null;
        window.clearTimeout(values.timer);
        if(values.enter) {
            video.current.currentTime = currentTime;
            timer = window.setTimeout(() => {
                setCurrentTime( (currentTime === values.duration ) ? 0 : 
                    (currentTime + (values.duration / 6))
                    );
                window.clearTimeout(timer);
            }, 600 );
        } else 
            video.current.currentTime = 0;
    },[values.enter, currentTime]);
    
    return (
        <Box sx={{position: 'relative', overflow: 'hidden'}}>
             <Box {...otherProps} sx={{
            display: !values.load && 'none'
        }} ref={video} component="video" preload='auto' onLoadedData={handleLoad} loop />
            { !values.load ?
            <Skeleton
                variant="rectangular"
                height={190}
                width={'100%'} 
            />
            :
            (<Box sx={{
                height: '100%',
                width: '100%',
                position: 'absolute',
                display: 'block',
                top: 0,
                "&:hover": {
                    bgcolor: theme.palette.action.selected,
                    cursor: 'pointer'
                }
            }}
            onMouseEnter={handleMouse}
            onMouseLeave={handleMouse}
            component="a"
            target="_blank"
            href={otherProps.src}
            >
                <Chip
                    sx={{
                        position: 'absolute',
                        right: 10,
                        bottom: 10
                    }}
                    color="primary"
                    variant="contained"
                    label={formatTimer(values.duration)}
                />
            </Box>)
            }
        </Box>
    )
}

export default Video;