import { 
    Button, 
    Box, 
    Grid, 
    useMediaQuery, 
    Typography, 
    Checkbox, 
    //Card, 
    Alert,
    CardHeader,
    CardContent,
    CardActions,
    Dialog,
    DialogContent,
    IconButton
} from "@mui/material";
import { LoadingButton } from '@mui/lab';
import { useRef, useState, useContext } from "react";
import { useData, useSetting } from "../treatments/globalData";
//import BoxCard from "./BoxCard";
import FieldController from "./FieldController";
import regExpBase from "../config/regExpBase";
import axios from "axios";
import serverPath from "../treatments/severPath";
import capStr from "../treatments/capStr";
import * as localStorageData from '../treatments/localStorageData';
import { /*Navigate,*/ useNavigate } from "react-router-dom";
import { CurrentSession } from "./Auth";
import CloseIcon  from "@mui/icons-material/Close";

function SignIn(props) {
    const { screen, text, local } = useData();
    const isMiddleScreen = useMediaQuery(screen);
    const [, setSession] = useContext(CurrentSession);
    const [setting, setSetting] = useSetting();
    const redirect = useNavigate();
    const [values, setValues] = useState({
        error: null,
        checked: false, 
        loading: false,
        email: useRef(),
        password: useRef(),
        stayConnexcd: useRef()
    });

    const handleSubmit = (event) => {
        event.preventDefault();
        if(values.email.current && values.password.current) {
            setValues({...values, 'checked': false, loading: true});
            const route = serverPath('api/auth/login');
            axios.post(route,{
                email: values.email.current,
                password: values.password.current
            }).then((result) => {
                if(result.data) {
                    const user = {
                        token: result.data.token,
                        firstName: result.data.userFname,
                        lastName: result.data.userLname,
                        middleName: result.data.userMname,
                        email: result.data.userEmail,
                        grade: result.data.userGrade,
                        password: values.password.current,
                        id: result.data.userId,
                        geidConfig: {
                            docTypes: result.data.docTypes,
                            permission: result.data.userGrade.permission
                        }
                    };
                    localStorageData.set("session", user);
                    if(values.stayConnexcd.current.checked)
                        localStorageData.set("local", {...local, cookie: user});
                    
                    setValues({...values, 'checked': false, loading: false});
                    setSession(user);
                    redirect('/home');
                }

            }).catch((error) => {
                const message = error.response ? error.response.data.error : 'system';
                setValues({...values, 'checked': false, loading: false, error: message});

            })
           
        } else {
            setValues({...values, 'checked': true});
        }
    }

    return (
        <Box 
            component={Dialog}  
            open={Boolean(setting.logIn)}
        >
            <Box component={DialogContent} sx={{position: 'relative'}}>
                <IconButton 
                    sx={{position: 'absolute', right: '10px', top: '10px'}}
                    onClick={setSetting.onClose('logIn')}
                >
                    <CloseIcon/>
                </IconButton>
                <Box 
                    component={CardHeader} 
                    title="Connexion"
                    sx={{mb:0,pb:0}}
                />
                <Box component="form" onSubmit={handleSubmit}>
                    <Box component={CardContent}>
                        <Grid container spacing={isMiddleScreen ? .5 : 2}>
                                <Grid item xs={12} md>
                                    <FieldController
                                        label="Email"
                                        type="text"
                                        checking={values.checked}
                                        icon={true}
                                        fullWidth
                                        ref={values.email}
                                        regExp={regExpBase.email}
                                        helperTextError={capStr(text.input.error.email.format)}
                                        helperTextSuccess={capStr(text.input.validate.format)}
                                        size="small"
                                    />
                                </Grid>
                                <Grid item xs={12} md>
                                    <FieldController
                                        label="Mot de passe"
                                        type="password" 
                                        regExp={/.{1,}/}
                                        checking={values.checked}
                                        icon={true}
                                        ref={values.password}
                                        helperTextSuccess={capStr(text.input.validate.champ)}
                                        size="small"
                                        fullWidth
                                    />
                                    <Typography  sx={{mt:.2}} align={isMiddleScreen ? 'right' : 'left'}>
                                        <Button size="small">{text.input.error.password.forgot} ?</Button>
                                    </Typography>
                                </Grid>
                                <Grid item xs={12}> 
                                    <Box sx={{}}>
                                        <label>
                                            <Checkbox size="small" inputRef={values.stayConnexcd}/>
                                            <Typography component="span" variant="body2">Restez connecté </Typography>
                                        </label>
                                        {Boolean(values.error) && <Alert severity="error">
                                            {values.error === 'system' ? text.server.error.content : values.error} 
                                        </Alert>}
                                    </Box>
                                </Grid>
                        </Grid>
                        <Box component={CardActions} sx={{mt:0, mb:0, p:0}}> 
                            <LoadingButton 
                                type="submit" 
                                variant="contained" 
                                size="small"
                                loading={values.loading}
                            fullWidth={!isMiddleScreen}>
                            connexion
                            </LoadingButton>
                        </Box>
                    </Box>
                </Box>
            </Box>
        </Box> 
     )

}

export default SignIn;