export const WorkSpaceContext = createContext(null);
const WorkSpaceProvider = WorkSpaceContext.Provider;

const useWorkSpaceData = (init) => {
    const [values, setValues] = useState({
        panel: 0,
        uploads: [],
        data: [],
        collectiveData: [],
        error: null,
        loading: true,
        updateData: true,
        keys: 'documents;images;videos',
        fileForm: null,
        navUpload: null,
    });

    const actions = {
        handleChangeProps(props, value) {
            setValues({...values, ...(typeof props === 'string' ? {[props] : value} : props)})
        }
    };
    return [values, actions];
};

function WorkSpace(props) {
    const [currentSession, setSession] = useContext(CurrentSession);
    const inputHidden = useRef();
    const theme = useTheme();
    const uploadeButton = useRef(null);
    const [values, actions] = useWorkSpaceData({
        docTypes: currentSession.geidConfig.docTypes,
        role: currentSession.grade.role
    });
    const [value, action] = useSetting();
    const { text, screen } = useData();
    const icons = [ CleaningServicesIcon ];
    const isMiddleScreen = useMediaQuery(screen);
    const [settings, setSettings] = useSettingTreatment();

    const currentUploads = values.uploads
    .filter((upload) => (upload.state === 'current')).length;
    const uploadsData = values.uploads
    .filter((upload) => (!upload.delete)).length;

    const handleChange = (event) => {
        const [ file ] = event.target.files;
        if(file)
            actions.handleChangeProps({
                fileForm: {
                    file: file,
                    input: inputHidden
                }
            })
    };

    const handleOpenFileForm = (event) => {
        if(inputHidden.current) 
            inputHidden.current.click();
        //actions.handleChangeProps({fileForm: true})
    }

    useEffect(() => {
        values.uploads.forEach((dataRequest) => {
            if(dataRequest) {
                if(dataRequest.state === 'start') {
                    dataRequest.send();
                    dataRequest.state = 'current';
                    actions.handleChangeProps({uploads: [...values.uploads]});
                }
                dataRequest.xhr.onload = (event) => {
                    if(event.target.status >= 200 && event.target.status <= 400) {
                        dataRequest.state = 'finish';
                        actions.handleChangeProps({uploads: [...values.uploads]});
                    }
                    
                }  
            }
        });
    },[values.uploads, values.navUpload]);

    return (
            <WorkSpaceProvider value={[values, actions]}>
                <input hidden type="file" onChange={handleChange} ref={inputHidden} />
                <AppContentBox>
                    <AppHeader 
                        title={text.applications.workspace.title}
                        icon={
                            <WorkIcon
                                sx={{position: 'relative', top: '5px'}}
                            />
                        }
                        sx={{
                           zIndex: theme.zIndex.modal
                        }}
                    >
                      {isMiddleScreen  ?
                      (<Box 
                      sx={{
                            display:'flex', 
                            flexDirection: 'row', 
                            alignItems: 'center',
                            flex:1,
                            '&>*': {
                                m:1,
                            }
                        }}>
                            
                            <Box sx={{ flexGrow: 1, ml: 10}}>
                            </Box>
                            <Button 
                                startIcon={<NoteAddIcon/>}
                                size="small"
                                onClick={handleOpenFileForm}
                                children={'ajouter un fichier'}
                                variant="contained"
                                sx={{mr: 1}}
                            />
                            <Tooltip arrow title={'historique de chargement'}>
                                <IconButton 
                                    sx={{position: 'relative'}} 
                                    onClick={(event) => {
                                        actions.handleChangeProps({
                                            navUpload: event.target
                                        })
                                    }}
                                    ref={uploadeButton}
                                >
                                    <Badge 
                                        variant="dot" 
                                        overlap="circular" 
                                        color="primary"
                                        invisible={!Boolean(uploadsData)}
                                    >
                                            {currentUploads ?
                                            <CircularProgress
                                                sx={{
                                                    position: 'absolute',
                                                    top: -2,
                                                    left: -2
                                                }}
                                                size={30}
                                            /> : null}
                                            <FileUploadIcon />
                                    </Badge>
                                </IconButton>
                            </Tooltip>
                            <Tooltip arrow title={'paramètre'}>
                                <IconButton 
                                    onClick={action.onOpen('settingOptions')}
                                sx={{mr:1}}>
                                        <SettingsIcon/> 
                                </IconButton>
                            </Tooltip>
                            <Tooltip arrow title={'profil'}>
                                <Avatar color="primary" 
                                    sx={{bgcolor: 'primary.main'}}
                                    children={currentSession.lastName.charAt(0)}
                                /> 
                            </Tooltip>
                      </Box>):
                      (<Box>
                          <IconButton
                            onClick={action.onOpen('settingNavMobile')}
                            >
                                <MenuIcon/>
                            </IconButton>
                      </Box>)
                    }
                    </AppHeader>
                    <Content/>
                </AppContentBox>

                <Menu
                    anchorEl={uploadeButton.current}
                    open={Boolean(values.navUpload)}
                    onClose={() => {
                        actions.handleChangeProps({
                            navUpload: null
                        })
                    }}
                >
                    <Box
                        sx={{width: 350, height: 500, m:1, position: 'relative' }}
                    >
                        <Typography
                            component={Typography}
                            variant="h6"
                            color="primary"
                            sx={{mb:1}}
                        >Historique de téléchargement</Typography>
                        <IconButton 
                            onClick={() => {
                                actions.handleChangeProps({
                                    navUpload: null
                                })
                            }}
                            sx={{position: 'absolute', right: 0, top:0}}
                        >
                            <CloseIcon />
                        </IconButton>

                        {
                        uploadsData === 0 &&
                        <Box
                            sx={{
                                position: 'absolute',
                                top: '50%',
                                left: '50%',
                                transform: 'translate(-50%, -50%)',
                                }}
                        >
                          <Typography 
                            children="historique vide, aucun téléchargent en cours"
                            color="text.secondary"
                            align="center"
                          />  
                        </Box>
                    }
                    <List>
                        {
                            values.uploads.map((item, index, table) => (!item.delete) && (
                                <UploadProgress 
                                uploadLength={table.length} 
                                {...item} 
                                key={index}
                                currentIndex={index}
                                remove={
                                    () => {

                                        values.uploads[index].delete = true;
                                        actions.handleChangeProps({uploads: values.uploads});

                                    }
                                } 
                                />
                            ))
                        }
                    </List>
                    </Box>
                </Menu>
            </WorkSpaceProvider>
        );
}

function Content(props) {

    const { text } = useData();
    const [settings, setSettings] = useSettingTreatment();
    const [currentSession] = useContext(CurrentSession);
    const [values, actions] = useContext(WorkSpaceContext);
    const marginWidthMax = 300;
    const marginWidthMin = 70;
    const theme = useTheme();
    const containerDetail = useRef();
    const[contentValues, setContentValues] = useState({
        anchorEl: null,
        options: [],
        detailNav: null,
        fileName: null,
        send: null,
        sendNav: null
    });

    const icons = {
        doc: TopicIcon,
        photo: InsertPhotoIcon,
        video: MovieIcon
    }
    
    const handleChangeProps = (props) => {
        setContentValues({...contentValues, ...props});
    }

    const handleDetails = (fileInfos) => {
        handleChangeProps({
            detailNav: contentValues.detailNav ? null: {
                name: fileInfos.name,
                date: fileInfos.createdAt
            }
        })
    };

    const handleDeleteFile = (fileName) => {
        const user = localStorageData.parse({
            userId: currentSession.id,
            path: values.keys.split(';')[values.panel],
            filename: fileName
        });
        const route = serverPath(`api/stuff/workspace/${user}`);
        axios.delete(route,{
            headers: {
                'Authorization': `Bearer ${currentSession.token}`,
            }
        }).then((result) => {
            handleGetData(values, actions);
        }).catch((error) => {
                console.log(error.toString());
        });
    }

    const handleEditeFileName = (name) => {
        handleChangeProps({
            fileName: contentValues.fileName ? null : name
        })
    }
    const handleFileNavInfo = (file) => (event) => {
        console.log(file);
        handleChangeProps({
             
            anchorEl: event.target,
            options: [
                {
                    label: "supprimer",
                    icon: <DeleteIcon/>,
                    action(){
                        handleDeleteFile(file.name);
                        
                    },
                    close: true
                },
                {
                    label: "renommer",
                    icon: <EditIcon/>,
                    action(){
                        handleEditeFileName(file.name)
                    }
                },
                {
                    label: "détails",
                    icon: <InfoIcon/>,
                    action(){
                        handleDetails(file);
                    }
                },
                {
                    label: "envoyer vers ...",
                    icon: <SendIcon/>,
                    children: true,
                    action() {
                        handleChangeProps({send: {file: file}});
                    }
                }
            ]
        })
    }
    const handlePanels = (index) => () => {
        if(values.panel !== index)
            actions.handleChangeProps('panel', index);
    };
    const handleGetData = (values, actions) => {
        const user = localStorageData.parse({
            userId: currentSession.id,
            path: values.keys.split(';')[values.panel]
        });
        const route = serverPath(`api/stuff/workspace/${user}`);

        axios.get(route, {
            headers: {
                'Authorization': `Bearer ${currentSession.token}`,
            }
        }).then((result) => {
            const cloneData = [...values.data];
            const isUpdate = localStorageData.parse(cloneData[values.panel]) !== localStorageData.parse(result.data)
            cloneData[values.panel] = result.data;
            actions.handleChangeProps({
                ...values, 
                data: cloneData, 
                loading: false, 
                updateData: isUpdate && values.data[values.panel]
            });
        }).catch((error) => {
            console.log(error.toString());
        });
        /*
        const routeTest = serverPath('api/stuff/workspace');
        const form = new FormData();
        console.log(file.name);
        form.append('filename', file.name);
        form.append('userId', currentSession.id);
        form.append('path', values.keys.split(';')[values.panel]);
        form.append('file', file);
        axios({
            method: 'post',
            url: routeTest,
            data: form,
            headers: {
                'Authorization' : `Bearer ${currentSession.token}`,
            }
        }).then((result) => {

            console.log(result.data);

        }).catch((error) => {
            console.log(error.toString());
        });
*/
    };

    useEffect(() => {
       if((values.panel < 3) && values.loading)
            handleGetData(values, actions);
    }, [values.loading, values.panel]);

    useLayoutEffect (() => {
        if((values.panel < 3) && !values.data[values.panel]);
            actions.handleChangeProps({loading: true})
        if ((values.panel < 3) && values.data[values.panel]);
            handleGetData(values, actions);
    },[values.panel]) 

    return(
        <Box container component={Grid} spacing={0}>  
                <Box item component={Grid} sx={{
                    position: 'relative',
                    transition: theme.transitions.create('width', {
                        easing: theme.transitions.easing.sharp,
                        duration: theme.transitions.duration.leavingScreen,
                    }),
                    height: '100vh',
                    width: `${settings.workspace ? marginWidthMax : marginWidthMin}px`,
                    borderRight: `1px solid ${theme.palette.divider}`,
                    overflow: 'hidden',
                    marginLeft: 0,
                    ...(Boolean(settings.workspace) && {
                        transition: theme.transitions.create('width', {
                        easing: theme.transitions.easing.easeOut,
                        duration: theme.transitions.duration.enteringScreen,
                        }),
                        //marginLeft: `${marginWidthMax}px`,
                    }),
                }}>
                    <Box sx={{p: 1, alignContent: 'center', alignItems: 'center', textAlign: settings.workspace ? 'right' : 'center'}}>
                        { settings.workspace ?
                        (<IconButton
                            onClick={setSettings.onClose('workspace')}
                        >
                            <ChevronLeftIcon />
                        </IconButton>):
                        (<IconButton
                            onClick={setSettings.onOpen('workspace')}
                        >
                        <MenuIcon />
                        </IconButton>)
                        }
                    </Box>
                    <Divider/>
                        {
                            text.applications.workspace.list.map((item, index, table) => {
                                const Icon = icons[item.id]
                            return(
                                <Box  
                                {...(
                                    settings.workspace ?
                                    {
                                        component: ListItemButton,
                                        dense: true
                                    }:
                                    {
                                        style: {
                                            textAlign: 'center'
                                        },
                                        title: item.label
                                    }
                                )}
                                key={index} 
                                sx={{pt:1, pb:1, ...((values.panel === index && !settings.workspace) ? {
                                    bgcolor: 'primary.main',
                                    "& *": {
                                        color: 'white'
                                    }
                                } : {

                                })}}
                                onClick={handlePanels(index)}
                                >
                                    {Icon &&
                                    (settings.workspace ?
                                ( <ListItemIcon>
                                        <Icon />
                                    </ListItemIcon>) :
                                    (<Tooltip placement="right" enterDelay={1000} arrow title={item.label}>
                                        <IconButton>
                                            <Icon />
                                        </IconButton>
                                    </Tooltip>
                                    )
                                        )
                                    
                                    }
                                    { settings.workspace && <ListItemText>{item.label}</ListItemText>}
                                    
                                </Box>)
                            })
                        }
                    <Divider/>
                        {
                        settings.workspace ? 
                        (<Box>


                        </Box>) : (
                            <Box sx={{
                                textAlign: 'center',
                                height:300,
                                position: 'relative',

                            }}>
                                
                              
                            </Box>
                        )
                        }
                </Box>
                
                <Box
                    item component={Grid}
                    sx={{
                        padding: theme.spacing(1),
                        position: 'relative',
                        transition: theme.transitions.create('width', {
                            easing: theme.transitions.easing.sharp,
                            duration: theme.transitions.duration.leavingScreen,
                        }),
                        height: '90vh',
                        flex: 1,
                        flexGrow: 1,
                        ...(Boolean(settings.workspace) && {
                            transition: theme.transitions.create('width', {
                            easing: theme.transitions.easing.easeOut,
                            duration: theme.transitions.duration.enteringScreen,
                            }),
                        
                        }),
                    }}
                >
              <Box component={PerfectScrollbar} >
                <Box sx={{mb: 1}} component={Card}>
                        <CardMedia sx={{height: 200}} title="archive" image={require('../../assets/CIS-Controls-Telework-Guide-1200-768x401.png')} />
                </Box>
                <TabsUnstyled value={values.panel} 
                    ref={containerDetail}
        
                >
                    {(values.loading) ?
                        (<Box
                            sx={{
                                position: 'absolute',
                                top: '50%',
                                left: '50%',
                                transform: 'translate(-50%, -50%)',
                                }}
                        >
                        <CircularProgress
                                size={50}
                        /> 
                        </Box>) :
                        <Fragment>
                            <TabPanelUnstyled value={0}>
                                <AppViewerDoc 
                                    data={values.data[0]} md={3}
                                    actionsDetail={handleFileNavInfo} 
                                />
                            </TabPanelUnstyled>
                            <TabPanelUnstyled value={1}>
                                <AppViewerPicture 
                                    data={values.data[1] || []}
                                    actionsDetail={handleFileNavInfo} 
                                />
                            </TabPanelUnstyled>
                            <TabPanelUnstyled value={2}>
                                <AppViewerVideo 
                                    data={values.data[2] || []}
                                    actionsDetail={handleFileNavInfo} 
                                />
                            </TabPanelUnstyled>
                        </Fragment>
                    }
                </TabsUnstyled> 
              </Box>
              
              <Snackbar
                open={Boolean(values.updateData)}
                autoHideDuration={2000}
                onClose={() => {
                    actions.handleChangeProps({updateData: false})
                } }
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'right'
                }}
                message="mise à jours du contenu ..."
                action={
                    <IconButton
                        size="small"
                        color="inherit"
                        onClick={() => {
                            actions.handleChangeProps({updateData: false})
                        }}
                    >
                        <CloseIcon/>
                    </IconButton>
                }
            />
            </Box>
              <FileForm/>
            <FileNav
                anchorEl={contentValues.anchorEl}
                options={contentValues.options}
                onClose={() => {
                    handleChangeProps({
                        anchorEl: null,
                        options: []
                    })
                }}
            />
            <FileDetail
                ref={containerDetail}
                open={Boolean(contentValues.detailNav)}
                {...(
                    contentValues.detailNav ?
                    {
                        date: contentValues.detailNav.date,
                        name: contentValues.detailNav.name
                    }: {}
                )}
                onClose={handleDetails}
            />

            {
            Boolean(contentValues.fileName) &&
            (<FileEditorName
                open={Boolean(contentValues.fileName)}
                name={contentValues.fileName}
                onClose={handleEditeFileName}
                onEdite={() => {
                    handleGetData(values, actions);
                }}
            />)
            }
            <Drawer
                anchor="bottom"
                open={Boolean(contentValues.send)}
                onClose={() => {
                    setContentValues({...contentValues, send: null})
                }}
            >
                <List>
                    {[
                        {label:'Archive', id:"archives"}, 
                        {label:'Mediathèque', id:"mediaLibrary"}
                    ].map((item, index) => (
                    <ListItem button key={index}>
                        
                        <ListItemText 
                            primary={item.label} 
                            onClick={() => {
                                setContentValues({
                                    ...contentValues, 
                                    send: null, 
                                    sendNav: {
                                        title: item.label,
                                        type: values.keys.split(';')[values.panel],
                                        id: item.id,
                                        file: contentValues.send.file
                                    }
                                })
                            }}
                        />
                    </ListItem>
                    ))}
                </List>
                <Divider />
            </Drawer>
            <SendForm
                onClose={() => {
                    setContentValues({...contentValues, sendNav: null})
                }}
                open={Boolean(contentValues.sendNav)}
                {...( contentValues.sendNav ?
                    {
                        title: contentValues.sendNav.title,
                        type: contentValues.sendNav.type,
                        id: contentValues.sendNav.id,
                        file: contentValues.sendNav.file
                    }:{})}
            />
        </Box>
    )
}


export default WorkSpace;