function Home() {
    const { 
        text, 
        //local, 
        frameApps:apps, 
        documents, 
        screen  
    } = useData();
    const clearText = useRef(null);
    const isMiddleScreen = useMediaQuery(screen);
    const [currentSession] = useContext(CurrentSession);
    const authenticate = Boolean(currentSession);
    const [values, setValues] = useState({
        open: false,
        content: null,
        title: null
    });
    const handleClose = () => {
        setValues({
            ...values,
            open: false,
            content: null,
            title: null
        })
    };
    /*const handleClick = (props) => () => { 
        setValues({...values, ...props});
    }*/
  
    const frameApps = sortData(apps, "id").map((frame, index) => (
        {
            ...(sortData(text.home.frame.apps, "id")[index]),
            ...(sortData(appsIcon,"id")[index]),
            ...frame}
    ))

    return (
        <Box>
            <Grid container spacing={0}>
                <Box component={Grid} item xs={12}>
                    <Box sx={{overflow: 'hidden', pt:1, position: 'relative'}}>
                        <CarouselPanel
                            settings={{
                                onChange( index ){
                                    clearText.current('');
                                },
                               // fade: true
                            }}
                        >
                            {
                                carouselImages.map((img, index, t)=> 
                                (
                                <Box key={index}>
                                    <CardMedia 
                                        component="img"
                                        height={300}
                                        image={require('../assets/'+img.src+ '.jpg')}
                                    />
                                  <Box 
                                        sx={{
                                            position: 'absolute', width: isMiddleScreen ? 800 : '', height: '100%',
                                            //, 
                                            top: 0
                                        }}
                                        component={CardContent}
                                    >
                                    <Box
                                        sx={{
                                            background: 'rgba(0, 0, 0, .3)',
                                            backdropFilter: 'blur(15px)',
                                            p:1,
                                            display: 'inline-block'
                                        }}
                                    >
                                        <Typography variant="h4" color="white">
                                            {img.title}
                                        </Typography>
                                        <Typography
                                            children={img.content}
                                            color="white"
                                            sx={{
                                                fontSize: 20
                                            }}
                                        />
                                    </Box>
                                    </Box>
                                </Box>
                             ))
                            }
                        </CarouselPanel>
                    </Box>
                </Box>
                <Grid item xs={12}>
                    <Box component={Card} elevation={0}>
                        <Box 
                            component={CardHeader}
                            title={text.home.geid.title}
                            sx={{mb:0, pb:0}}
                        />
                        <Box component={CardContent} >
                            <Typography variant="body2" color="text.secondary">{text.home.geid.content}</Typography>
                        </Box>
                        <Box component={CardActions} >
                        {!authenticate && 
                        <Button 
                            variant="contained" 
                            size="small" 
                            to="/home/signup" 
                            LinkComponent={Link} 
                        >{text.home.geid.button}</Button>}
                        </Box>
                    </Box>
                </Grid>
            </Grid>
            <Grid container spacing={1} sx={{pr:1, pl:1}}>
                {
                    documents.map((doc, index) => (
                        <Box key={index} item md={12/5} xs={12} component={Grid}>
                            <Book 
                                cover={`${process.env.PUBLIC_URL}/images/${doc.image}`}
                                title={capStr(doc.title)}
                                link={ `${process.env.PUBLIC_URL}/documents/${doc.link}`}
                            />
                        </Box>
                    ))
                }
            </Grid>
            <Grid container spacing={1} sx={{p:1}}>
                {
               sortData(frameApps, "title").map((frameApp, indexApp) => {
                   
                const frameInfos = {
                    title: (
                        <Typography>
                            <frameApp.icon
                                sx={{
                                    fontSize: '25px', 
                                    mr: .2,
                                    position: 'relative',
                                    top: 5
                                }}
                            /> 
                            {capStr(frameApp.title)}
                        </Typography>),
                    content: frameApp.content,
                    image: require('../assets/' + frameApp.image),
                    buttonTitle: text.home.frame.button.open + ' ' + frameApp.title,
                    link: frameApp.path ,
                };
    
                return (
                    <Box key={indexApp} md={12/5} xs={12} item component={Grid}>
                        <FrameApp
                            {...frameInfos}
                            
                        />
                    </Box>
                    )})
                }
            </Grid>
            <Footer/>
            <Modal
                open={values.open}
                onClose={handleClose}
            >
                <Box sx={{
                    position: 'absolute',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    width: 400,
                    bgcolor: 'background.paper',
                    border: '2px solid #000',
                    boxShadow: 24,
                    p: 4,
                    }}>
                    <Typography variant="h6" component="h2">
                        {values.title}
                    </Typography>
                    <Typography sx={{ mt: 2 }}>
                        {values.content}
                    </Typography>
                </Box>
            </Modal>
        </Box>
    );
}

