import React, { useEffect, useRef, useState } from 'react';
import { Editor } from '@tinymce/tinymce-react';
import { CircularProgress, useTheme } from '@mui/material';
import { Box } from '@mui/material';
import '../../styles/note.css';
import initConfig from './init';

export default function EditorText() {
  const editorRef = useRef(null);
  const inputFile = useRef(null);
  const theme = useTheme();
  const [values, setValues] = useState({
    loading: false,
  });

  /*const log = () => {
    if (editorRef.current) {
      console.log(editorRef.current.getContent());
    }
  };*/
  useEffect(() => {
    if(!values.loading && editorRef.current) console.log(editorRef.current.iframeElement
      .contentWindow.document.body.focus())

  },[values.loading])
  return (
    <Box component={values.loading ? "div" : "form"}>
       <input hidden ref={inputFile}/>
      {
        values.loading &&
        <Box sx={{position: 'relative', height: 350, textAlign:'center', ml: 'auto'}}>
          <CircularProgress size={50} sx={{mt: 25}}/>
        </Box>
      }
      <Box sx={{display: values.loading ? 'none' : ''}}>
        <Editor
          onInit={(evt, editor) => editorRef.current = editor}
          //initialValue="<p>...</p>"
          onLoadContent={()=> {
              setValues({...values, loading: false});
          }}
          init={{
            ...initConfig,
            file_picker_callback (callback, value, meta) {
              inputFile.current.click();
              
              /* Provide file and text for the link dialog */
              if (meta.filetype === 'file') {
                
                callback('https://www.google.com/logos/google.jpg', { text: 'My text' });
                
              }
          
              /* Provide image and alt text for the image dialog */
              if (meta.filetype === 'image') {
                //callback('https://www.google.com/logos/google.jpg', { alt: 'My alt text' });
              }
          
              /* Provide alternative source and posted for the media dialog */
              if (meta.filetype === 'media') {
                callback('movie.mp4', { source2: 'alt.ogg', poster: 'https://www.google.com/logos/google.jpg' });
              }
            }
          }}
          apiKey="33ba4vme0xl5wrumyggywiormvv4uhvixrmcoxhv38hg4g2b"
        />
      </Box>
    </Box>
  );
}
