import CryptoJS from "crypto-js";

const SECRET_SIGN = "";
export const encrypt = (text) => typeof text === 'string' ? CryptoJS.AES.encrypt(text, SECRET_SIGN).toString() : null;
export const decrypt = (code) => typeof code === 'string' ? CryptoJS.AES.decrypt(code, SECRET_SIGN).toString(CryptoJS.enc.Utf8) : null;
