function sortData (data, key, ref='', rev=false ) {
    
    const keys = [];
    const newData = [];
    if(key) {
        data.forEach((elm) => {
            keys.push(elm[key]);
        });
        keys.sort();
        if(rev) keys.reverse();
    
        keys.forEach((elm) => {
            data.forEach((obj) => {
                if(elm)
                    if( (new RegExp(ref,'i')).test(elm) && obj[key] === elm ) newData.push(obj);
            });          
        });
    }
    return (key === undefined ? data : newData );
}

export default sortData;
