export const archiveContext = createContext(null);
const ArchiveProvider = archiveContext.Provider;

const useArchiveData = (init) => {
    const [values, setValues] = useState({
        doc: '',
        indexDoc: 0,
        role: init.role,
        loading: true,
        docTypes: init.docTypes,
        archives: [],
        fullScreen: null,
        tab: 0,
    });
    const actions = {
        handleChangeProps(props, value) {
            setValues({...values, ...(typeof props === 'string' ? {props : value} : props)})
        }
    };
    return [values, actions];
};

function Archive(props) {
    const [currentSession, setSession] = useContext(CurrentSession);
    const [values, actions] = useArchiveData({
        docTypes: currentSession.geidConfig.docTypes,
        role: currentSession.grade.role
    });
    const [value, action] = useSetting();
    const { text, screen } = useData();
    const icons = [ CleaningServicesIcon ];
    const isMiddleScreen = useMediaQuery(screen);
    const [settings, setSettings] = useSettingTreatment();

    return (
            <ArchiveProvider value={[values, actions]}>
                <AppContentBox>
                    <AppHeader 
                        title={text.applications.archive.title}
                        icon={
                            <ArchiveIcon
                                sx={{position: 'relative', top: '5px'}}
                            />
                        }
                    >
                      {isMiddleScreen  ?
                      (<Box 
                      sx={{
                            display:'flex', 
                            flexDirection: 'row', 
                            alignItems: 'center',
                            flex:1,
                            '&>*': {
                                m:1
                            }
                        }}>
                            <Box sx={{ flexGrow: 1, ml: 10}}>
                                <TabsList
                                    onChange={(event, value) => {
                                        actions.handleChangeProps({
                                            tab: value,
                                            loading: true
                                        })
                                    }}
                                    tabsProps={{
                                        value: values.tab
                                    }}
                                >
                                    {
                                    text.applications.archive.onglets.map((elm, index) => {
                                    const Icon = icons[index];
                                    return  ( ( Boolean( currentSession.geidConfig.permission && currentSession.geidConfig.permission.find((item) => item === elm.permission)) || elm.permission === undefined) &&
                                        <Tab
                                            label={elm.title}
                                            key={index}
                                            startIcon={Icon && <Icon/>}
                                        />
                                        );
                                    })
                                    }
                                </TabsList>
                            </Box>
                            <Box sx={{ flexGrow: 1, ml: 10}}>
                                <SearchInput />
                            </Box>
                            <IconButton 
                                onClick={action.onOpen('settingOptions')}
                            >
                                <SettingsIcon/>
                            </IconButton>
                      </Box>):
                      (<Box>
                          <IconButton
                            onClick={action.onOpen('settingNavMobile')}
                            >
                                <MenuIcon/>
                            </IconButton>
                      </Box>)
                    }
                    </AppHeader>
                    <Content/>
                </AppContentBox>
            </ArchiveProvider>
        );
}

function Content(props) {
    const { screen } = useData();
    const [values, actions] = useContext(archiveContext);
    const [currentSession] = useContext(CurrentSession);
    const [settings, setSettings] = useSettingTreatment();
    const theme = useTheme();
    const isMiddleScreen = useMediaQuery(screen);
    const[contentValues, setContentValues] = useState({
        anchorEl: null,
        options: [],
        detailNav: null,
        fileName: null,
        send: null,
        sendNav: null
    });
    
    const handleChangeProps = (props) => {
        setContentValues({...contentValues, ...props});
    }

    const handleDetails = (fileInfos) => {
        handleChangeProps({
            detailNav: contentValues.detailNav ? null: {
                name: fileInfos.name,
                date: fileInfos.createdAt
            }
        })
    };

    const handleDeleteFile = (file) => {
        const user = localStorageData.parse({
            userId: currentSession.id,
            frozenId: file._id,
            frozenType: 'ressource'
        });

        const route = serverPath(`api/stuff/frozen/${user}`);
        axios.delete(route,{
            headers: {
                'Authorization': `Bearer ${currentSession.token}`,
            }
        }).then((result) => {
            handleGetData(values, actions);
            console.log(result.data)
        }).catch((error) => {
                console.log(error.toString());
        });
    }

   /* const handleEditeFileName = (file) => {
        console.log(file)
        handleChangeProps({
            send: null, 
            sendNav: {
                title: '...',
                type: 'resourece',
                id: 'archives',
                //file: contentValues.send.file
            }
        })
    }*/
    const handleValidateData = (file) => {
        const route = serverPath('api/stuff/archives');
        axios({
            method: 'post',
            data: {
                userId: currentSession.id,
                frozenId: file._id,
            },
            url: route,
            headers: {
                'Authorization': `Bearer ${currentSession.token}`,
            }
        }).then((result) =>  {
            handleGetData(values, actions);
        }).catch((error) =>  {
            console.log(error.toString());
        });
    }
    const handleFileNavInfo = (file) => (event) => {
        console.log(file);
        handleChangeProps({
             
            anchorEl: event.target,
            options: [
                {
                    label: "supprimer l'archive",
                    icon: <DeleteIcon/>,
                    action(){
                        handleDeleteFile(file);
                        
                    },
                    close: true
                },
                /*{
                    label: "modifier les informations",
                    icon: <EditIcon/>,
                    action(){
                        handleEditeFileName(file)
                    }
                },*/
                {
                    label: "infos",
                    icon: <InfoIcon/>,
                    action(){
                        handleDetails(file);
                    }
                },
                {
                    label: "valider l'archive",
                    icon: <BookmarkAddedIcon/>,
                    children: true,
                    action() {
                        handleValidateData(file);
                    }
                }
            ]
        })
    }

    const handleChage = (event, data) => {
        actions.handleChangeProps( typeof data === 'object' ? 
        ({
            doc: data.value, 
            indexDoc:  data.index,
            loading: true,
        }) : ({
            doc: '', 
            indexDoc: data,
            loading: true
        }));
    };

    const handleChoiceDataContent = (data, ext, filertKey, sortKey) => {
        const selectData = data.filter((elm) => 
            (~ext.indexOf(getFileExtension(elm[filertKey])))
        );
        const classifyData = sortData(selectData, sortKey);
        return classifyData;
    };

    const handleGetData = (values, actions) => {
        const params = localStorageData.parse({
			userId: currentSession.id,
            ...(values.tab === 0 ? {
                role: values.role,
                type: Boolean(values.doc.trim()) ? values.doc : null
            } : {}),
            ...(values.tab === 1 ? {
                where: 'archives'
            } : {}),
        });
        const route = serverPath(`api/stuff/${['archives/', 'frozen/'][values.tab]}${params}`);
        axios.get(route, { 
            headers: {'Authorization' : `Bearer ${currentSession.token}`} 
        }).then((result) => {
            console.log(result.data)
            if(result.data) 
                actions.handleChangeProps({...values, loading: false, archives: result.data});
        }).catch((error) => {
                console.log(error.toString());
        })
    }

    useEffect(() => {
      if(values.loading) handleGetData(values, actions);
    }, [values.loading], [values.tab]);

    const marginWidth = 400;
  
    return(
        <Box>
            <Box>
                <Box  sx={{zIndex: 100000, position: 'relative', overflow: 'inherit'}} component={Card}>
                    <TabsList
                        tabsProps={{
                            value: values.indexDoc,
                        }}
                        sx={{m:1}}
                        indicator={false}
                        onChange={handleChage}
                    >
                       <Tab 
                            label="tous"
                            variantFocus={true}
                        /> 
                        {
                         [...values.docTypes].map((doc, index) => {
                           return ( doc.subtypes ?
                            (<TabGroup 
                                key={index}
                                defaultValue={doc.name}
                                variantFocus={true}
                                options={[doc.name,...doc.subtypes]}
                            />) :
                           (<Tab 
                            key={index} 
                            label={doc.name}
                            defaultValue={doc.name}
                            variantFocus={true}
                            value={index + 1}
                            />)) 
                         })
                        }
                    </TabsList>
                </Box> 
            </Box>
            <Box>
                {isMiddleScreen && 
                    <Fragment>
                        <TreeStructure
                            width={marginWidth}
                            open={Boolean(settings.treeStruture)}
                            onClose={setSettings.onClose('treeStruture')}
                        />
                        {!settings.treeStruture &&
                        <Fab
                            sx={{
                                position: 'fixed', 
                                bottom: 15, 
                                left: 15,
                                zIndex: theme.zIndex.modal
                            }}
                            color="primary"
                            onClick={setSettings.onOpen('treeStruture')}
                        >
                            <AccountTreeIcon />  
                        </Fab>}
                    </Fragment>
                }

                <Box
                    sx={{
                        padding: theme.spacing(1),
                        position: 'relative',
                        transition: theme.transitions.create('margin', {
                            easing: theme.transitions.easing.sharp,
                            duration: theme.transitions.duration.leavingScreen,
                        }),
                        marginLeft: 0,
                        ...(Boolean(settings.treeStruture) && {
                            transition: theme.transitions.create('margin', {
                              easing: theme.transitions.easing.easeOut,
                              duration: theme.transitions.duration.enteringScreen,
                            }),
                            marginLeft: `${marginWidth}px`,
                          }),
                    }}
                >
                    <Box component={isMiddleScreen ? PerfectScrollbar : 'div'}
                        sx={{height: '80vh', overflow: isMiddleScreen ? 'hidden' : 'auto'}}
                    >
                      <Box
                        sx={{
                            mb:1,
                            height: isMiddleScreen ? 500 : '',
                        }}
                      >
                        {!values.fullScreen &&
                        <Box sx={{height: isMiddleScreen ? 200 : 80 , position: 'relative', mb: 1}} component={Card}>
                            <CardMedia sx={{height: 200}} title="archive" image={require('../../assets/band1_bandeau-collecte.jpg_img.jpg')} />
                        </Box>}
                        
                        {
                        values.loading ?   
                        ( <Box
                            sx={{position: 'relative', height: 350, textAlign:'center', ml: 'auto'}}
                        >
                            <CircularProgress size={50} sx={{mt: 25}}/>
                        </Box> ):
                            ( <Box>
                                <AppTabList
                                    data={[
                                        {
                                            label: 'documents',
                                            content: (
                                                <AppViewerDoc 
                                                    data={handleChoiceDataContent(
                                                        values.archives, 
                                                        fileExtensionBase.doc,
                                                        ['contentUrl', 'fileUrl'][values.tab], 
                                                        'designation'
                                                    )}
                                                    actionsDetail={handleFileNavInfo}
                                                    md={Boolean(settings.treeStruture) ? 3 : (12/5)}
                                                    fullScreen={values.fullScreen === null ? null : values.fullScreen === 'doc'}
                                                    onOpen={ (value)=> { actions.handleChangeProps({fullScreen: value} )}}
                                                />
                                            )
                                        },
                                        {
                                            label: 'photos',
                                            content: (
                                                <AppViewerPicture
                                                data={handleChoiceDataContent(
                                                    values.archives, 
                                                    fileExtensionBase.photo,
                                                    ['contentUrl', 'fileUrl'][values.tab], 
                                                    'designation'
                                                )}
                                                actionsDetail={handleFileNavInfo}
                                                md={Boolean(settings.treeStruture) ? 4 : 3}
                                                fullScreen={values.fullScreen === null ? null : values.fullScreen === 'photo'}
                                                onOpen={ (value)=> { actions.handleChangeProps({fullScreen: value} )}}
                                            />
                                            )
                                            
                                        },
                                        {
                                            label: 'vidéos',
                                            content: (
                                                <AppViewerVideo
                                                data={handleChoiceDataContent(
                                                    values.archives, 
                                                    fileExtensionBase.video,
                                                    ['contentUrl', 'fileUrl'][values.tab], 
                                                    'designation'
                                                )}
                                                actionsDetail={handleFileNavInfo}
                                                md={Boolean(settings.treeStruture) ? 4 : 3}
                                                fullScreen={values.fullScreen === null ? null : values.fullScreen === 'photo'}
                                                onOpen={ (value)=> { actions.handleChangeProps({fullScreen: value} )}}
                                            />
                                            )
                                            
                                        }
                                    ]}
                                />
                               
                                {
                                    //other viewer here................
                                }
                            </Box> )
                        }
                        </Box>
                    </Box>
                </Box>
            </Box>
            <FileNav
                anchorEl={contentValues.anchorEl}
                options={contentValues.options}
                onClose={() => {
                    handleChangeProps({
                        anchorEl: null,
                        options: []
                    })
                }}
            />
             <FileDetail
                //ref={containerDetail}
                open={Boolean(contentValues.detailNav)}
                {...(
                    contentValues.detailNav ?
                    {
                        date: contentValues.detailNav.date,
                        name: contentValues.detailNav.name
                    }: {}
                )}
                onClose={handleDetails}
            />
            <SendForm
                onClose={() => {
                    setContentValues({...contentValues, sendNav: null})
                }}
                open={Boolean(contentValues.sendNav)}
                {...( contentValues.sendNav ?
                    {
                        title: contentValues.sendNav.title,
                        type: contentValues.sendNav.type,
                        id: contentValues.sendNav.id,
                        file: contentValues.sendNav.file
                    }:{})}
            />
        </Box>
    )
}

export default Archive;