import React,{Fragment, useState , memo, useContext} from 'react';
import { useLocation } from 'react-router-dom';
import {
    useMediaQuery,
    Box, 
    Button, 
    ButtonGroup,
    AppBar,
    Toolbar,
    IconButton, 
    Avatar, 
    //Fab,
    Tooltip
  } from '@mui/material';
import HomeIcon  from '@mui/icons-material/Home';
import ContactSupportIcon from '@mui/icons-material/ContactSupport';
import SettingsIcon from '@mui/icons-material/Settings';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import TheatersIcon from '@mui/icons-material/Theaters';
import AppsIcon from '@mui/icons-material/Apps';
import MenuIcon from '@mui/icons-material/Menu';
import { useData, useSetting } from '../treatments/globalData';
import TabsList,{Tab} from '../components/TabsList';
import GeidLogo from './GeidLogo';
//import * as localStorageData from '../treatments/localStorageData';
import { /*SettingOptions, SettingNavMobile, */AppsMenu } from './Settings';
import { CurrentSession } from './Auth';

const iconsTabs = {
    home: HomeIcon,
    help: ContactSupportIcon,
    mediaLibrary: TheatersIcon,
    account: AccountCircleIcon

}

function Header() { 

    const { screen } = useData();
    //const [value, action] = useSetting();
    const isMiddleScreen = useMediaQuery(screen);
    const route = useLocation();
  
    return ( (!~route.pathname.indexOf('apps')) &&
        <Fragment>
         { isMiddleScreen && (<Links/>) }
            <AppBarNav/>
        </Fragment>
    )
    
}

function Links() {

    const { links } = useData();

    return (
        <Box
        sx={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            '& > *': { m: 1,},
             bgcolor: 'primary.main',
            pt:3,
            pb:3
          }}
        >
            <ButtonGroup sx={{"& *": {color: 'white'}}} color="inherit" variant="text" aria-label="text button group">
                <Button children="République démocratique du congo">
                </Button>
                {
                    links.slice(0, 3).map((link, index)=> (<Button key={index}>{link.title}</Button>))
                }
            </ButtonGroup>
        </Box>
    )
}

function AppBarNav() {
    const { screen, onglets, text:textContent } = useData();
    const { pathname } = useLocation();
    const [currentSession] = useContext(CurrentSession)
    const [, setSetting] = useSetting();
    //const { local, session } = localStorageData.get();
    const { header:text } = textContent;
    const isMiddleScreen = useMediaQuery(screen);
    const authenticate = Boolean(currentSession ? currentSession.token : null);
    const initIndex = onglets.findIndex((route) => 
    pathname === route.path || ~pathname.indexOf('home'));
    const [indexRoute, setIndexRoute] = useState(initIndex);
    const handleChange = (event, newValue) => {
        setIndexRoute(newValue);
    };
    const [, action] = useSetting();

    return(
        <AppBar color='default' position="sticky">
         { !isMiddleScreen &&
          <Toolbar>
            <GeidLogo   
                sx={{ flexGrow: 1}}
            />
            <IconButton
                onClick={action.onOpen('settingNavMobile')}
            >
                <MenuIcon/>
            </IconButton>
          </Toolbar>}
          <Toolbar>
            { isMiddleScreen && <GeidLogo
                sx={{ flexGrow: .5}}
            />}
            <TabsList 
                tabsProps={{
                    value: indexRoute,
                    sx:{
                        flexGrow:1
                    }
                }}
                onChange={handleChange}    
            >
                {
                    onglets.map((tab, index) => {
                        const IconTab = iconsTabs[tab.title];
                        const label = text.onglets;
                        return (tab.type === 'public' ? true : currentSession) && (
                            <Tab 
                            label={label[tab.title]} 
                            key={index}
                            link={tab.path}
                            startIcon={IconTab ? <IconTab/> : null}
                        />
                        )
                    })
                }
            </TabsList>
           
            { isMiddleScreen &&
            <Fragment>
                <AppsMenu/>
                
                { (authenticate) ?
                 (<Fragment>
                    <Box  
                    sx={{ 
                        flexGrow: .1,
                        display: 'flex',
                        flexDirection: 'row',
                        alignItems: 'center',
                        '& > *': { m: 1,}
                    }}>
                        
                    </Box>
                        <Tooltip arrow title={'applicatios'}>
                            <IconButton
                                onClick={action.onOpen('appsMenu')}
                            >
                                <AppsIcon/>
                            </IconButton>
                        </Tooltip>
                        
                 </Fragment>):
                 (<Box sx={{mr: 1}}>
                     <Button 
                        children="connexion"
                        variant="contained"
                        size="small"
                        onClick={setSetting.onOpen('logIn')}
                     />
                 </Box>)
               }
                <Tooltip arrow title={'paramètre'}>
                    <IconButton 
                        onClick={action.onOpen('settingOptions')}
                    >
                        <SettingsIcon/>
                    </IconButton>
                </Tooltip>
                {
                currentSession &&
                (<Tooltip arrow title={'votre profil'}>
                    <IconButton 
                        size='small'
                        onClick={action.onOpen('profileNav')}
                    >
                        <Avatar 
                            children={currentSession && currentSession.lastName[0]}
                            sx={{bgcolor: 'primary.main', width: 35, height: 35}}
                        />
                    </IconButton> 
                </Tooltip>)
                }
            </Fragment>
            }  
          </Toolbar>
        </AppBar>
    )
}

export default memo(Header);